E["item:ancient-egg"] = {t="item",n="Ancient Egg",z="hinterlands",s="The Ancient Egg is a troll relic hidden in Jintha'Alor in the Hinterlands. Yeh'kinya seeks it because the Prophecy of Mosh'aru says it can contain Hakkar's essence.",h="The Ancient Egg is a troll relic hidden in Jintha'Alor in the Hinterlands.",sec={{t="A Relic in Jintha'Alor",b="Deep within the troll city of Jintha'Alor, the Ancient Egg lies in a cave beyond the amphitheater. Yeh'kinya seeks it in Tanaris, where he studies the Prophecy of Mosh'aru. The prophecy names the egg as a vessel for Hakkar's essence. Yeh'kinya fears that the world may depend on it.",sp=0}},faq={{q="What is the Ancient Egg?",a="The Ancient Egg is a troll relic from the age of vast troll empires. The Prophecy of Mosh'aru says it can hold Hakkar's essence.",al={"ancient egg","what egg","troll egg"}},{q="Where is the Ancient Egg?",a="The Ancient Egg lies in a cave deep within Jintha'Alor, behind the amphitheater at the city's summit in the Hinterlands.",al={"egg location","where egg","jintha alor egg"}},{q="Who wants the Ancient Egg?",a="Yeh'kinya in Tanaris seeks the Ancient Egg because of what the Prophecy of Mosh'aru says it can do.",al={"yehkinya egg","who wants it","bring egg to"}},{q="Why does Yeh'kinya want it?",a="Yeh'kinya believes the Ancient Egg may be the only way to keep the world safe from Hakkar's evil.",al={"why egg","hakkar egg","prophecy egg"}}},ang={["race:Troll"]="As a troll, the Ancient Egg recalls the vast empires of your people and the power bound to their old relics."},kw={"ancient egg","hakkar","hinterlands","jintha'alor","mosh'aru","troll relic","yeh'kinya"},rel={"quest:4787","zone:hinterlands","npc:yeh-kinya","topic:troll"},src={"Wowpedia: Ancient Egg","The Ancient Egg"}}
E["item:atal-ai-tablet-fragment"] = {t="item",n="Atal'ai Tablet Fragment",z="hinterlands",s="The Atal'ai Tablet Fragment is a troll souvenir Rhapsody Shindigger found near a sunken temple. Brohann Caskbelly values it as an Atal'ai artifact.",h="The Atal'ai Tablet Fragment is a troll souvenir Rhapsody Shindigger found near a sunken temple.",sec={{t="A Troll Souvenir",b="Rhapsody Shindigger found the Atal'ai Tablet Fragment after falling into the water near a sunken temple. He says creepy trolls surrounded him there, and he swam away with this fragment. He gives it to you for Brohann Caskbelly in Stormwind.",sp=0}},faq={{q="What is the Atal'ai Tablet Fragment?",a="It is a troll keepsake that Rhapsody Shindigger picked up near a sunken temple.",al={"atal'ai tablet","tablet fragment","troll fragment"}},{q="Where did Rhapsody find it?",a="Rhapsody says he found the fragment in the water near a sunken temple, surrounded by trolls.",al={"where's the fragment from","rhapsody tablet","temple souvenir"}},{q="Who should I give the fragment to?",a="Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.",al={"who wants this","brohann tablet","where deliver fragment"}},{q="Why does Brohann want it?",a="Brohann recognizes the fragment as an Atal'ai artifact and calls it quite a find.",al={"why brohann wants it","what's it worth","atal'ai artifact"}}},kw={"atal'ai","atal'ai tablet fragment","brohann caskbelly","fragment","rhapsody shindigger","sunken temple","tablet","troll"},rel={"quest:1469","item:atal-ai-artifact","zone:hinterlands","topic:troll"},src={"Wowpedia: Atal'ai Tablet Fragment","Wowpedia: Rhapsody's Tale"}}
E["item:faranell-s-parcel"] = {t="item",n="Faranell's Parcel",z="hinterlands",s="Faranell's Parcel carries a potent sample of Witherbark spider venom from the Hinterlands to the Undercity. Master Apothecary Faranell receives it for study and possible new uses.",h="Faranell's Parcel carries a potent sample of Witherbark spider venom from the Hinterlands to the Undercity.",sec={{t="A Sample Sent South",b="In the Hinterlands, Apothecary Lydon sends Faranell's Parcel to his superior, Master Apothecary Faranell, in the Undercity. The parcel holds venom taken from the Witherbark's spider god. Lydon has tested its strength on rabbits and believes Faranell will want to examine the poison himself.",sp=0},{t="Faranell's Work",b="At the Apothecarium, Master Apothecary Faranell receives the parcel and hears that Lydon considers its poison exceptionally potent. He is already working on new applications for it. The Royal Apothecary Society hopes the sample will yield further uses.",sp=0}},faq={{q="What is in Faranell's Parcel?",a="Faranell's Parcel contains a sample of venom taken from the Witherbark's spider god.",al={"what's in the parcel","faranell parcel contents"}},{q="Who sent the parcel?",a="Apothecary Lydon provides Faranell's Parcel for delivery to his superior, Master Apothecary Faranell.",al={"who gave me the parcel","lydon parcel"}},{q="Who is the parcel for?",a="Master Apothecary Faranell receives the parcel at the Apothecarium in the Undercity.",al={"who gets it","faranell delivery"}},{q="Why does Faranell want the venom?",a="Lydon believes Faranell will want to test the potent poison himself, and Faranell is working on new applications for it.",al={"why send venom","what does faranell want"}},{q="How strong is the venom?",a="Lydon says a drop killed nearly two dozen rabbits, though he notes some were very young and small.",al={"venom strength","is the spider poison powerful"}}},ang={["faction:Horde"]="As a member of the Horde, you carry Lydon's venom sample to the Undercity for the Royal Apothecary Society.",["race:Undead"]="As Forsaken, you serve a society whose apothecaries study poisons such as the Witherbark venom in this parcel."},kw={"apothecarium","apothecary lydon","faranell","faranell's parcel","master apothecary faranell","royal apothecary society","spider venom","undercity","witherbark"},rel={"quest:2938","npc:master-apothecary-faranell","subzone:apothecarium","topic:royal-apothecary-society","zone:undercity","zone:hinterlands"},src={"Wowpedia: Faranell's Parcel","Venom to the Undercity"}}
E["item:final-message-to-the-wildhammer"] = {t="item",n="Final Message to the Wildhammer",z="hinterlands",s="The Final Message to the Wildhammer is a spear Otho Moji'ko sends from Revantusk Village to Aerie Peak. Its grisly display is meant to show the Wildhammer dwarves that the trolls mean business.",h="The Final Message to the Wildhammer is a spear Otho Moji'ko sends from Revantusk Village to Aerie Peak.",sec={{t="A Spear for Aerie Peak",b="At Revantusk Village in the Hinterlands, Otho Moji'ko gives you a blood-drenched spear wrapped in gryphon feathers. He wants you to plant it by the well in the center of Aerie Peak, where the Wildhammer dwarves will see it. The message is blunt, and Otho hopes you return alive.",sp=0}},faq={{q="What is the Final Message to the Wildhammer?",a="It is a blood-drenched spear wrapped in gryphon feathers, sent by Otho Moji'ko to Aerie Peak.",al={"final message","wildhammer spear","otho's message"}},{q="Who gives you the spear?",a="Otho Moji'ko gives you the spear at Revantusk Village in the Hinterlands.",al={"who is otho","who hands it over","troll who gives spear"}},{q="Where does the spear go?",a="Otho wants you to plant it by the well in the center of Aerie Peak.",al={"where to plant it","aerie peak well","where's the message"}},{q="Why send a bloody spear?",a="Otho wants the Wildhammer dwarves to see that the trolls mean business.",al={"why the spear","what does it mean","trolls mean business"}},{q="What happens when you place it?",a="Falstad Wildhammer yells when you place the spear, and you are marked for PvP.",al={"falstad yell","placing the message","wildhammer reaction"}}},ang={["race:Troll"]="As a troll, you carry Otho Moji'ko's threat into Aerie Peak, where he hopes the Wildhammer dwarves will see the strength of Revantusk.",["faction:Alliance"]="For the Alliance, the spear is a direct threat planted in the heart of Aerie Peak, among the Wildhammer dwarves."},kw={"aerie peak","final message","gryphon feathers","otho moji'ko","revantusk village","spear","well","wildhammer"},rel={"quest:7843","quest:7842","quest:7841","zone:hinterlands","topic:troll","topic:alliance"},src={"Wowpedia: Final Message to the Wildhammer","Wowpedia: The Final Message to the Wildhammer"}}
E["item:gadrin-s-parchment"] = {t="item",n="Gadrin's Parchment",z="hinterlands",s="Gadrin's Parchment is read at Shadra'Alor in the Hinterlands. Its words summon Shadra, whose venom Apothecary Lydon seeks in Tarren Mill.",h="Gadrin's Parchment is read at Shadra'Alor in the Hinterlands.",sec={{t="At Shadra'Alor",b="Deep in the Witherbark realm, Gadrin's Parchment is read at the altar of Shadra'Alor. Its words summon Shadra, the spider god. Her venom is sought by Apothecary Lydon in Tarren Mill.",sp=0}},faq={{q="What does Gadrin's Parchment do?",a="Gadrin's Parchment is read at Shadra'Alor to summon Shadra, the spider god.",al={"what is parchment for","gadrin parchment use"}},{q="Where do I read the parchment?",a="Read Gadrin's Parchment at the altar of Shadra'Alor, deep in the Witherbark realm of the Hinterlands.",al={"where use parchment","shadra altar location"}},{q="Who is Shadra?",a="Shadra is the spider god summoned by reading Gadrin's Parchment at Shadra'Alor.",al={"shadra spider","spider god"}},{q="Who wants Shadra's venom?",a="Apothecary Lydon in Tarren Mill seeks Shadra's venom.",al={"venom for who","lydon venom"}}},kw={"apothecary lydon","gadrin","gadrin's parchment","hinterlands","parchment","shadra","shadra'alor","venom","witherbark"},rel={"quest:2937","item:shadra-s-venom","zone:hinterlands","subzone:tarren-mill"},src={"Wowpedia: Gadrin's Parchment","Summoning Shadra (Classic)"}}
E["item:groddoc-liver"] = {t="item",n="Groddoc Liver",z="hinterlands",s="Groddoc Liver comes from the apes of Feralas. Rhapsody Shindigger needs it for a drink he hopes will loosen his tongue about a frightening flight over a swamp.",h="Groddoc Liver comes from the apes of Feralas.",sec={{t="A Bitter Ingredient",b="Rhapsody Shindigger asks for Groddoc Liver in the Hinterlands, along with Roc Gizzards and Ironfur Livers. He plans to distill the three ingredients into a Kalimdor Kocktail. The drink, he says, may help him speak of the horrors of a flight over a swamp.",sp=0}},faq={{q="Where do Groddoc Livers come from?",a="Groddoc Livers come from Groddoc Apes in Feralas.",al={"where find groddoc liver","groddoc liver source"}},{q="Who wants Groddoc Liver?",a="Rhapsody Shindigger in the Hinterlands asks for three Groddoc Livers to make his Kalimdor Kocktail.",al={"who needs this liver","rhapsody liver"}},{q="What is Groddoc Liver used for?",a="Rhapsody Shindigger uses Groddoc Liver with Roc Gizzards and Ironfur Livers for a Kalimdor Kocktail.",al={"groddoc liver use","why need liver"}},{q="Why is Rhapsody making the drink?",a="Rhapsody says he needs a stronger drink before he can tell you about a frightening flight over a swamp.",al={"why cocktail","rhapsody wants drink"}}},kw={"feralas","groddoc ape","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},rel={"quest:1452","quest:1451","zone:feralas","zone:hinterlands","item:ironfur-liver","item:roc-gizzard"},src={"Wowpedia: Groddoc Liver","Rhapsody's Kalimdor Kocktail"}}
E["item:hinterlands-honey-ripple"] = {t="item",n="Hinterlands Honey Ripple",z="hinterlands",s="Crates of Hinterlands Honey Ripple sit at an abandoned Horde base near Skulk Rock. Dran Droffers wants the bottles for a packaging scheme.",h="Crates of Hinterlands Honey Ripple sit at an abandoned Horde base near Skulk Rock.",sec={{t="Crates at Skulk Rock",b="The crates at Skulk Rock hold Hinterlands Honey Ripple, an unusual drink sought by Dran Droffers. The abandoned Horde base lies among slime covered ruins, where the bottles must be gathered with care. Their intact packaging matters to the scheme Dran has in mind.",sp=0}},faq={{q="Where can I find Hinterlands Honey Ripple?",a="Hinterlands Honey Ripple is in crates around the abandoned Horde base near Skulk Rock.",al={"honey ripple location","where ripple","hinterlands bottles"}},{q="Who wants the Honey Ripple?",a="Dran Droffers seeks Hinterlands Honey Ripple for a packaging scheme involving Malton’s father.",al={"who wants ripple","dran droffers ripple","ripple for who"},sp=1},{q="Why does Dran need the bottles intact?",a="Dran says the bottles must not be bruised because jostling spoils the drink’s bouquet. He has empty packaging for the ripple.",al={"why bottles unbruised","don't bruise ripple","ripple packaging"}},{q="What is Hinterlands Honey Ripple?",a="It is a bottled drink kept in crates at the abandoned Horde base near Skulk Rock.",al={"honey ripple","what is ripple","hinterlands drink"}}},ang={["faction:Horde"]="The bottles lie in crates at an abandoned Horde base near Skulk Rock."},kw={"dran droffers","hinterlands honey ripple","honey ripple","horde crates","malton","ripple","skulk rock"},rel={"quest:77","zone:hinterlands","topic:horde"},src={"Wowpedia: Hinterlands Honey Ripple","Wowpedia: A Sticky Situation"}}
E["item:huntsman-malkhor-s-bones"] = {t="item",n="Huntsman Malkhor's Bones",z="hinterlands",s="Huntsman Malkhor's Bones are remains found in a sludge pit at Jintha'alor. Huntsman Markhor seeks them so his twin brother can receive a proper burial.",h="Huntsman Malkhor's Bones are remains found in a sludge pit at Jintha'alor.",sec={{t="A Brother's Remains",b="At Jintha'alor in the Hinterlands, Huntsman Malkhor's Bones lie in a refuse pit among the Vilebranch's oozes. Huntsman Markhor asks you to recover them with his brother's skull. He hopes to take the remains to Yayo'jin for a proper burial.",sp=0}},faq={{q="Where are Malkhor's bones?",a="Huntsman Malkhor's Bones lie in a sludge pit at Jintha'alor, near the top of the temple.",al={"malkhor bones location","where find the bones"}},{q="Who wants Malkhor's bones?",a="Huntsman Markhor at Revantusk Village wants his twin brother's remains so he can arrange a proper burial.",al={"who needs the bones","markhor brother bones"}},{q="Who was Malkhor?",a="Huntsman Malkhor was Huntsman Markhor's twin brother. The Vilebranch captured and killed him in a raid.",al={"malkhor backstory","markhor twin"},sp=1},{q="Why recover the bones?",a="Markhor hopes to take Malkhor's remains to Yayo'jin for a proper burial.",al={"why bones matter","malkhor burial"}},{q="What happened to Malkhor's remains?",a="The Vilebranch fed Malkhor's remains to the oozes and wolves at Jintha'alor.",al={"malkhor remains","what happened to his bones"},sp=1}},kw={"hinterlands","huntsman malkhor's bones","huntsman markhor","jintha'alor","malkhor","separation anxiety","sludge pit","twin brother","vilebranch"},rel={"quest:7849","item:huntsman-malkhor-s-skull","zone:hinterlands"},src={"Wowpedia: Huntsman Malkhor's Bones","Wowpedia: Separation Anxiety (quest)"}}
E["item:huntsman-malkhor-s-skull"] = {t="item",n="Huntsman Malkhor's Skull",z="hinterlands",s="Huntsman Malkhor's Skull is part of the remains Huntsman Markhor seeks in Jintha'alor. He hopes to give his twin brother a proper burial.",h="Huntsman Malkhor's Skull is part of the remains Huntsman Markhor seeks in Jintha'alor.",sec={{t="A Brother's Remains",b="Among the skulls in Jintha'alor lies one belonging to Huntsman Malkhor, twin brother of Huntsman Markhor of Revantusk Village. The Vilebranch killed Malkhor and left his remains to the oozes and wolves near the temple's upper reaches. Markhor asks you to recover the skull and bones so his brother's soul may be at peace.",sp=0}},faq={{q="Who does the skull belong to?",a="The skull belongs to Huntsman Malkhor, the twin brother of Huntsman Markhor of Revantusk Village.",al={"malkhor skull","whose skull","huntsman malkhor"}},{q="Where is Malkhor's skull?",a="Malkhor's skull rests in a pile of skulls on the upper tier of Jintha'alor.",al={"skull location","where skull","jintha'alor skull"}},{q="Who wants Malkhor's remains?",a="Huntsman Markhor wants you to recover his twin brother's skull and bones for a proper burial.",al={"who wants remains","markhor brother","separation anxiety"}},{q="How did Malkhor die?",a="The Vilebranch killed Malkhor in a raid and fed his remains to oozes and wolves.",al={"what happened malkhor","malkhor death","vilebranch killed"},sp=1},{q="Why is Markhor searching for the remains?",a="Markhor hopes to have Malkhor's remains prepared for a proper burial and his soul put at peace.",al={"why recover skull","malkhor burial","brother remains"}}},kw={"huntsman malkhor","huntsman markhor","jintha'alor","malkhor's skull","revantusk village","separation anxiety","vilebranch"},rel={"quest:7849","item:huntsman-malkhor-s-bones","zone:hinterlands"},src={"Wowpedia: Huntsman Malkhor's Skull","Wowpedia: Separation Anxiety (quest)"}}
E["item:ironfur-liver"] = {t="item",n="Ironfur Liver",z="hinterlands",s="Ironfur Liver comes from Ironfur bears in Feralas. Rhapsody Shindigger needs it for a drink he hopes will loosen his tongue about a swamp adventure.",h="Ironfur Liver comes from Ironfur bears in Feralas.",sec={{t="A Stronger Drink",b="Rhapsody Shindigger in the Hinterlands asks you to bring three Ironfur Livers for his Kalimdor Kocktail. He pairs them with Groddoc Livers from Feralas and Roc Gizzards from Tanaris. The drink, he says, will help him speak of his flight over the swamp.",sp=0}},faq={{q="Where do Ironfur Livers come from?",a="Ironfur Livers come from Ironfur bears in Feralas.",al={"ironfur liver source","where get liver"}},{q="Who wants Ironfur Liver?",a="Rhapsody Shindigger in the Hinterlands wants three Ironfur Livers for his Kalimdor Kocktail.",al={"who needs this","rhapsody liver"}},{q="Why does Rhapsody need these livers?",a="Rhapsody needs Ironfur Livers, Groddoc Livers, and Roc Gizzards to make a strong Kalimdor Kocktail. He hopes the drink will help him talk about his swamp adventure.",al={"why liver","what's the cocktail for"}},{q="What else goes into the Kalimdor Kocktail?",a="The Kalimdor Kocktail also calls for Groddoc Livers from Feralas and Roc Gizzards from Tanaris.",al={"cocktail ingredients","other organs"}}},kw={"feralas","groddoc liver","ironfur bear","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},rel={"quest:1452","zone:feralas","quest:1451","item:groddoc-liver","item:roc-gizzard"},src={"Wowpedia: Ironfur Liver","Rhapsody's Kalimdor Kocktail"}}
E["item:nimboya-s-pike"] = {t="item",n="Nimboya's Pike",z="hinterlands",s="Nimboya’s Pike is a weapon Nimboya lends for a grim message to the Witherbark trolls of the Hinterlands. Their betrayal of Thrall has brought the Horde’s anger to their villages.",h="Nimboya’s Pike is a weapon Nimboya lends for a grim message to the Witherbark trolls of the Hinterlands.",sec={{t="A Grim Message",b="In Stranglethorn, Nimboya gives you his pike and sends you north to the Hinterlands. The Witherbark trolls once stood with the Horde, but they betrayed Thrall. Nimboya means for them to see that betrayal answered. He names Hiri’watha and Zun’watha as places where his message may be left.",sp=0}},faq={{q="Who is Nimboya’s Pike for?",a="Nimboya lends the pike so you can carry his message to the Witherbark trolls in the Hinterlands.",al={"nimboyas pike","pike for who"}},{q="Why does Nimboya want to punish the Witherbarks?",a="The Witherbark trolls were once allies to the Horde, but they betrayed Thrall.",al={"why punish witherbark","withercark betrayal"}},{q="Where should I take the pike?",a="Nimboya sends you to the Hinterlands, northeast of Tarren Mill, to leave the message at Hiri’watha or Zun’watha.",al={"where pike go","hinterlands pike"}},{q="What is Nimboya’s Laden Pike?",a="It is Nimboya’s Pike bearing Witherbark skulls, meant to be placed in one of their villages as a grim message.",al={"laden pike","skull pike"},sp=1}},ang={["faction:Horde"]="The pike carries the Horde’s anger toward the Witherbarks for betraying Thrall, once their ally."},kw={"grim message","hinterlands","horde","laden pike","nimboya","nimboya's pike","pike","thrall","witherbark"},rel={"quest:2932","zone:hinterlands","topic:horde","topic:troll"},src={"Wowpedia: Nimboya's Pike","Wowpedia: Grim Message"}}
E["item:rin-ji-s-secret-quest-item"] = {t="item",n="Rin'ji's Secret",z="hinterlands",s="In the Hinterlands, a tablet marked with Witherbark troll script may hold something valuable. Oran Snakewrithe in Undercity’s Magic Quarter is asked to decipher it.",h="In the Hinterlands, a tablet marked with Witherbark troll script may hold something valuable.",sec={{t="Troll Markings",b="Rin'ji's Secret is a tablet found among the troubles of the Hinterlands. Its surface bears the markings of the Witherbark trolls, and its meaning is unknown. Oran Snakewrithe, a scholar of Witherbark matters in Undercity, may be able to read it.",sp=0}},faq={{q="What is Rin'ji's Secret?",a="Rin'ji's Secret is a tablet covered in Witherbark troll markings. Its meaning is a mystery.",al={"rinji secret","rin'ji tablet","what is the tablet"}},{q="Who can read the tablet?",a="Oran Snakewrithe, a scholar of Witherbark trolls in Undercity's Magic Quarter, may be able to decipher the tablet.",al={"who deciphers it","Oran tablet","magic quarter scholar"}},{q="Where is the tablet from?",a="The tablet is tied to Rin'ji's troubles in the Hinterlands.",al={"where found","hinterlands tablet","rinji location"}},{q="Is Rin'ji's Secret valuable?",a="The tablet may be valuable, but its worth is uncertain until its markings are understood.",al={"tablet worth","valuable tablet","rinji secret value"}}},ang={["race:Troll"]="The tablet bears Witherbark markings, so its mystery concerns the history and lore of a troll tribe."},kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","rinji","secret","tablet","troll","undercity","witherbark"},rel={"quest:2782","quest:2742","zone:hinterlands","zone:undercity","subzone:magic-quarter","topic:troll","quest:8273"},src={"Wowpedia: Rin'ji's Secret (quest item)","Rin'ji's Secret (quest)"}}
E["item:roc-gizzard"] = {t="item",n="Roc Gizzard",z="hinterlands",s="Roc Gizzards come from the rocs of Tanaris. In the Hinterlands, Rhapsody Shindigger needs three for a strong drink.",h="Roc Gizzards come from the rocs of Tanaris.",sec={{t="A Stronger Drink",b="Rhapsody Shindigger in the Hinterlands asks you to bring him three Roc Gizzards from Tanaris. He needs them for a Kalimdor Kocktail, along with livers from Feralas. Rhapsody says the drink will help him speak of a frightening flight over a swamp.",sp=0}},faq={{q="Where do Roc Gizzards come from?",a="Rocs, Fire Rocs, and Searing Rocs in Tanaris yield Roc Gizzards.",al={"roc gizzard location","where find gizzards","tanaris roc parts"}},{q="Who needs Roc Gizzards?",a="Rhapsody Shindigger in the Hinterlands needs three Roc Gizzards for his Kalimdor Kocktail.",al={"who wants roc gizzards","rhapsody gizzard","gizzards for who"}},{q="What is a Kalimdor Kocktail?",a="It is a strong drink Rhapsody Shindigger means to make with Roc Gizzards and livers from Feralas.",al={"rhapsody drink","what drink needs gizzards","kalimdor cocktail"}},{q="Why does Rhapsody want the drink?",a="Rhapsody says he needs something strong before he can speak of a frightening flight over a swamp.",al={"why rhapsody needs drink","what makes him talk","rhapsody swamp story"}}},kw={"fire roc","kalimdor kocktail","rhapsody shindigger","roc","roc gizzard","searing roc","tanaris"},rel={"quest:1452","quest:1451","zone:tanaris","zone:hinterlands","item:groddoc-liver","item:ironfur-liver"},src={"Wowpedia: Roc Gizzard","Rhapsody's Kalimdor Kocktail"}}
E["item:shackle-key-the-hinterlands"] = {t="item",n="Shackle Key",z="hinterlands",s="The Shackle Key is held by Hitah'ya the Keeper in a cave near Jintha'alor. Elder Torntusk needs it to loosen his bindings and return home.",h="The Shackle Key is held by Hitah'ya the Keeper in a cave near Jintha'alor.",sec={{t="The Bound Elder",b="At Jintha'alor in the Hinterlands, Elder Torntusk waits for the key to his bindings. Hitah'ya the Keeper holds it in a nearby cave and is well guarded. Bring the key back to Torntusk so he can be freed and return home.",sp=0}},faq={{q="Who has the Shackle Key?",a="Hitah'ya the Keeper holds the Shackle Key in a cave near Jintha'alor.",al={"who has the key","key holder","hitahya key"}},{q="What is the Shackle Key for?",a="The Shackle Key loosens Elder Torntusk's bindings so he can return home.",al={"what key does","key purpose","torntusk key"}},{q="Where is the key?",a="Hitah'ya the Keeper holds the key in a cave near Jintha'alor in the Hinterlands.",al={"key location","where key","nearby cave"}},{q="Who needs the key?",a="Elder Torntusk at Jintha'alor needs the key to free himself from his bindings.",al={"who wants key","who needs it","elder torntusk"}}},kw={"bindings","elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","shackle key"},rel={"quest:7846","quest:7845","quest:7847","zone:hinterlands"},src={"Wowpedia: Shackle Key (The Hinterlands)","Wowpedia: Recover the Key!"}}
E["item:shadra-s-venom"] = {t="item",n="Shadra's Venom",z="hinterlands",s="Shadra's Venom is taken from the spider god in the Hinterlands. Apothecary Lydon in Tarren Mill needs it after Shadra is summoned.",h="Shadra's Venom is taken from the spider god in the Hinterlands.",sec={{t="Venom for Lydon",b="At Shadra'Alor in the Hinterlands, the parchment calls Shadra from her lair. Her venom is carried to Apothecary Lydon in Tarren Mill, who waits for it.",sp=0}},faq={{q="What is Shadra's Venom?",a="Shadra's Venom is taken from Shadra, the spider god of the Hinterlands.",al={"shadra venom","what venom"}},{q="Who needs Shadra's Venom?",a="Apothecary Lydon in Tarren Mill asks you to bring Shadra's Venom to him.",al={"who wants the venom","lydon venom"}},{q="Where do you get Shadra's Venom?",a="Shadra's Venom comes from Shadra at the altar of Shadra'Alor in the Hinterlands.",al={"where venom","get shadra venom"}},{q="How is Shadra summoned?",a="Read Gadrin's Parchment at the altar of Shadra'Alor, deep within the Witherbark realm in the Hinterlands.",al={"summon shadra","shadra altar"}}},kw={"apothecary lydon","gadrin's parchment","hinterlands","shadra","shadra'alor","shadra's venom","spider god","tarren mill"},rel={"quest:2937","item:gadrin-s-parchment","zone:hinterlands","subzone:tarren-mill"},src={"Wowpedia: Shadra's Venom","Summoning Shadra (Classic)"}}
E["item:sharpbeak-s-feather"] = {t="item",n="Sharpbeak's Feather",z="hinterlands",s="Sharpbeak's feather carries a trace of the young gryphon sought in the Hinterlands. Thadius Grimshade hopes its link to Sharpbeak will let his divining magic find him.",h="Sharpbeak's feather carries a trace of the young gryphon sought in the Hinterlands.",sec={{t="A Gryphon's Feather",b="At Nethergarde Keep, Thadius Grimshade asks for a feather taken from the nest where Sharpbeak sleeps. The diviner left Aerie Peak years ago to pursue darker knowledge, though he remains Wildhammer in his heart. He believes the feather may help him find the young gryphon.",sp=0},{t="A Sign of Promise",b="Thadius recognizes the feather as belonging to a fine gryphon. He believes Sharpbeak is destined for great things, if he survives to adulthood without harm. With the feather in hand, he bids you listen closely as he begins to divine the gryphon's whereabouts.",sp=0}},faq={{q="What is Sharpbeak's Feather for?",a="Thadius Grimshade uses Sharpbeak's Feather as a link for divining the young gryphon's whereabouts.",al={"sharpbeak feather","what feather for","feather use"}},{q="Where did the feather come from?",a="The feather was taken from the nest where the gryphon child Sharpbeak sleeps.",al={"sharpbeak feather source","where feather from","gryphon nest feather"}},{q="Who is Thadius Grimshade?",a="Thadius Grimshade is a Wildhammer diviner who left Aerie Peak years ago to pursue darker knowledge. He can be found in Nethergarde Keep's mage tower in the Blasted Lands.",al={"thadius backstory","who is thadius","grimshade"}},{q="What does Thadius think of Sharpbeak?",a="Thadius calls Sharpbeak a fine gryphon, destined for great things if he survives to adulthood undamaged.",al={"sharpbeak destiny","what thadius thinks","gryphon child"}}},ang={["race:Dwarf"]="As a dwarf, Sharpbeak's search touches the Wildhammer: Thadius Grimshade left Aerie Peak, yet still holds to his Wildhammer heart."},kw={"aerie peak","divination","gryphon","sharpbeak","sharpbeak's feather","thadius grimshade","wildhammer"},rel={"quest:2994","npc:thadius-grimshade","zone:hinterlands","subzone:nethergarde-keep","quest:2992","quest:2993"},src={"Wowpedia: Sharpbeak's Feather","Thadius Grimshade (quest)"}}
E["item:skylord-plume"] = {t="item",n="Skylord Plume",z="hinterlands",s="The Skylord Plume is taken from a Razorbeak Skylord in the Hinterlands. Huntsman Markhor at Revantusk Village seeks it as proof that one of these dangerous gryphons has been slain.",h="The Skylord Plume is taken from a Razorbeak Skylord in the Hinterlands.",sec={{t="A Hunter's Proof",b="At Revantusk Village, Huntsman Markhor asks you to bring him a Skylord Plume. The Razorbeak Skylords are rare gryphons of the Hinterlands, and Markhor says they prey on troll hunters. He wants one slain and its plume returned as proof.",sp=0}},faq={{q="What is the Skylord Plume?",a="The Skylord Plume comes from a Razorbeak Skylord, a rare gryphon of the Hinterlands.",al={"skylord plume","what plume","gryphon feather"}},{q="Who wants the Skylord Plume?",a="Huntsman Markhor at Revantusk Village wants a Skylord Plume brought to him.",al={"who wants plume","Markhor plume","Revantusk hunter"}},{q="Why does Markhor want it?",a="Markhor asks you to slay a Razorbeak Skylord and return with its plume as proof.",al={"why plume","Markhor wants feather","what's it for"}},{q="Where can I find a Razorbeak Skylord?",a="Razorbeak Skylords are rare gryphons that occupy the wilds of the Hinterlands.",al={"where skylord","find razorbeak","skylord location"}},{q="Why are the Skylords dangerous to trolls?",a="Markhor says the elder gryphons prey on troll hunters and raise offspring that also kill trolls.",al={"skylords and trolls","gryphon threat","why kill skylord"}}},ang={["race:Troll"]="Markhor says Razorbeak Skylords have devoured troll hunters in the Hinterlands, making their threat close to home.",["class:Hunter"]="Huntsman Markhor calls on you to hunt a rare gryphon that preys on hunters in the Hinterlands."},kw={"gryphon","hinterlands","markhor","razorbeak skylord","revantusk village","skylord plume","troll hunters"},rel={"quest:7830","zone:hinterlands","topic:troll","topic:hunter"},src={"Wowpedia: Skylord Plume","Wowpedia: Avenging the Fallen"}}
E["item:slagtree-s-lost-tools"] = {t="item",n="Slagtree's Lost Tools",z="hinterlands",s="Slagtree’s Lost Tools are a stolen set of smithing tools sought by Smith Slagtree in Revantusk Village. He asks you to search for them after Vilebranch trolls invade the village.",h="Slagtree’s Lost Tools are a stolen set of smithing tools sought by Smith Slagtree in Revantusk Village.",sec={{t="A Stolen Gift",b="At Revantusk Village, Smith Slagtree asks you to search for the tools taken when Vilebranch trolls invaded. He keeps a backup set, but these tools were given to him by a kind-hearted gnome who saved his life when he was young. They may lie near the Agol'watha or Shaol'watha temples, or at Skulk Rock. Slagtree wants this old gift returned.",sp=0}},faq={{q="Who wants Slagtree's Lost Tools?",a="Smith Slagtree of Revantusk Village wants his stolen tools returned.",al={"who wants the tools","slagtree tools","smith slagtree"}},{q="Why do the tools matter to Slagtree?",a="A kind-hearted gnome gave the tools to Slagtree after saving his life when he was a young orc.",al={"why are tools important","tools meaning","why does he want them"},sp=1},{q="Who stole the tools?",a="Vilebranch trolls stole Slagtree's tools when they invaded Revantusk Village.",al={"who took slagtree tools","vilebranch stole tools","stolen tools"}},{q="Where might the tools be?",a="The tools were spotted near the Agol'watha and Shaol'watha temples in the northeastern Hinterlands. Slagtree also suggests checking Skulk Rock.",al={"where are the tools","tool location","find slagtree tools"}},{q="Does Slagtree have other tools?",a="Slagtree has a backup set, but the stolen tools are precious because they came from the gnome who saved his life.",al={"backup tools","does he have spares","other smith tools"},sp=1}},ang={["race:Gnome"]="A gnome gave Slagtree the tools after saving his life when he was a young orc. Their gift remains precious to the smith.",["race:Orc"]="Slagtree remembers the tools as a gift from the gnome who saved his life when he was a young orc."},kw={"agol'watha","gnome","lost tools","revantusk village","shaol'watha","skulk rock","slagtree","smith slagtree","vilebranch","vilebranch hooligans"},rel={"quest:7839","zone:hinterlands","topic:gnome","topic:troll"},src={"Wowpedia: Slagtree's Lost Tools","Wowpedia: Vilebranch Hooligans"}}
E["item:troll-tribal-necklace"] = {t="item",n="Troll Tribal Necklace",z="hinterlands",s="Troll Tribal Necklaces are carried by forest trolls in the Hinterlands. The Wildhammers of Aerie Peak value them as proof that outsiders are willing to earn their regard.",h="Troll Tribal Necklaces are carried by forest trolls in the Hinterlands.",sec={{t="Aerie Peak’s Measure",b="Fraggar Thundermantle asks you to bring five Troll Tribal Necklaces to Aerie Peak. The Wildhammers are independent, and they judge those who seek their friendship by deeds. Fraggar counts the necklaces as a step toward winning their good graces.",sp=0}},faq={{q="Who wants Troll Tribal Necklaces?",a="Fraggar Thundermantle at Aerie Peak asks you to bring him five Troll Tribal Necklaces.",al={"who wants necklaces","fraggar necklace","necklace bounty"}},{q="Why do the Wildhammers want them?",a="Fraggar treats the necklaces as proof that you are willing to get your hands dirty and earn the Wildhammers’ regard.",al={"why necklaces","what are they for","wildhammer necklace"}},{q="Where do the necklaces come from?",a="Forest trolls in the Hinterlands carry Troll Tribal Necklaces.",al={"where find necklace","troll necklaces","necklace source"}},{q="How many necklaces does Fraggar ask for?",a="Fraggar asks you to bring five Troll Tribal Necklaces to Aerie Peak.",al={"how many","five necklaces","necklace count"}}},ang={["race:Dwarf"]="As a dwarf, you can earn the regard of the independent Wildhammer dwarves through deeds."},kw={"aerie peak","forest troll","fraggar thundermantle","hinterlands","troll necklace bounty","troll tribal necklace","wildhammer"},rel={"quest:2880","zone:hinterlands","topic:troll","quest:421"},src={"Wowpedia: Troll Tribal Necklace","Wowpedia: Troll Necklace Bounty"}}
E["item:undamaged-venom-sac"] = {t="item",n="Undamaged Venom Sac",z="hinterlands",s="An undamaged venom sac is a fresh spider sample sought by Apothecary Lydon in Tarren Mill. He wants its venom for experiments.",h="An undamaged venom sac is a fresh spider sample sought by Apothecary Lydon in Tarren Mill.",sec={{t="A Fresh Sample",b="Near the troll city of Shadra'Alor in the Hinterlands, spiders carry the venom sac Apothecary Lydon seeks. He needs an undamaged one, still fresh, for his experiments. Bring it to him in Tarren Mill.",sp=0}},faq={{q="Who wants the venom sac?",a="Apothecary Lydon in Tarren Mill wants a fresh, undamaged venom sac for experiments.",al={"who needs it","lydon venom sac"}},{q="Where can I find the spiders?",a="The spiders Lydon seeks dwell in the Hinterlands, near the troll city of Shadra'Alor.",al={"where spiders","venom sac location"}},{q="What does Lydon want to do with it?",a="Lydon wants to study the fresh venom in experiments on small animals.",al={"why does he need it","venom experiments"}},{q="Why must the sac be undamaged?",a="Lydon asks for an undamaged sac so its venom remains fresh for his experiments.",al={"fresh sac why","intact venom sac"}}},kw={"apothecary lydon","hinterlands","shadra'alor","spider","tarren mill","undamaged venom sac","venom"},rel={"quest:2934","zone:hinterlands","topic:troll"},src={"Wowpedia: Undamaged Venom Sac","Undamaged Venom Sac (quest)"}}
E["item:venom-bottle-quest-item"] = {t="item",n="Venom Bottle",z="hinterlands",s="A Venom Bottle holds a vile green venom found among the Witherbarks. An apothecary in Tarren Mill wants a sample.",h="A Venom Bottle holds a vile green venom found among the Witherbarks.",sec={{t="A Vile Sample",b="Among the Witherbarks’ many bottles is one filled with green venom. Its source seems to be an arachnoid creature, and an apothecary in Tarren Mill is eager to examine a sample.",sp=0}},faq={{q="What is in a Venom Bottle?",a="A Venom Bottle holds a vile, green venom. An apothecary in Tarren Mill judges it to come from an arachnoid creature.",al={"venom bottle contents","what's in the bottle"}},{q="Who wants the venom?",a="An apothecary in Tarren Mill wants a sample of the venom for study.",al={"who needs venom","tarren mill apothecary"}},{q="Where did the venom come from?",a="The apothecary in Tarren Mill judges the venom to come from an arachnoid creature.",al={"venom source","spider venom"}}},kw={"apothecary","arachnoid","tarren mill","venom","venom bottle","witherbarks"},rel={"quest:2933","subzone:tarren-mill","zone:hinterlands"},src={"Wowpedia: Venom Bottle (quest item)","Venom Bottles"}}
E["item:vessel-of-tainted-blood"] = {t="item",n="Vessel of Tainted Blood",z="hinterlands",s="The Vessel of Tainted Blood is a dark vessel found in Jintha'Alor. Its foul magic empowers the Vilebranch and clouds their minds.",h="The Vessel of Tainted Blood is a dark vessel found in Jintha'Alor.",sec={{t="Blood and Shadow",b="Primal Torntusk asks you to recover these vessels from Jintha'Alor in the Hinterlands. He says they carry the foul magic of the faceless blood God, empowering the Vilebranch and driving them to madness. He hopes to remove the taint and loosen the God’s grip.",sp=0}},faq={{q="What is the Vessel of Tainted Blood?",a="It is a vessel found in Jintha'Alor that radiates foul magic tied to the faceless blood God.",al={"tainted blood vessel","dark vessel","blood vessel"}},{q="Where can I find the vessels?",a="The Vessels of Tainted Blood are found throughout Jintha'Alor in the Hinterlands.",al={"where vessel","jintha alor vessels","find tainted vessels"}},{q="What do the vessels do?",a="Their foul magic empowers the Vilebranch and clouds their minds, driving them to madness.",al={"what vessel do","why are they bad","vessel magic"}},{q="Who wants the vessels?",a="Primal Torntusk at Revantusk Village wants you to bring him the tainted vessels so he can remove their taint.",al={"who wants blood vessels","torntusk vessels","primal torntusk"}}},kw={"dark vessel","faceless blood god","jintha'alor","primal torntusk","tainted blood","vessel of tainted blood","vilebranch"},rel={"quest:7850","quest:7847","zone:hinterlands"},src={"Wowpedia: Vessel of Tainted Blood","Wowpedia: Dark Vessels (Classic)"}}
E["quest:1444"] = {t="quest",n="Return to Fel'Zerul",z="hinterlands",s="In the Hinterlands, the Atal'ai Exile sends word to Fel'zerul in Stonard. The artifacts you brought are harmless, but the exile fears what Jammal'an the Prophet may do.",h="In the Hinterlands, the Atal'ai Exile sends word to Fel'zerul in Stonard.",sec={{t="Words from an Exile",b="The Atal'ai Exile once held Jammal'an the Prophet worthy of the high priesthood. Now the exile fears his unyielding faith in the prophecy may doom the Atal'ai, if it has not already. Speaking out earned the exile the name infidel and banishment from the Temple of Atal'Hakkar.\n\nThe artifacts you brought are harmless. Yet danger may lie in the summoning ritual, for Jammal'an may have found the right fetish enchantment. The world could be in great peril. Fel'zerul in Stonard waits to hear what the exile learned.",sp=0}},faq={{q="Where must I go to speak with Fel'zerul?",a="Fel'zerul is in Stonard.",al={"fel'zerul location","where is fel'zerul","turn in return to fel'zerul"}},{q="Why was the Atal'ai Exile banished?",a="The Atal'ai Exile spoke against Jammal'an the Prophet's unyielding faith in his prophecy, which the exile fears may destroy the Atal'ai. The exile was called an infidel and banished from the Temple of Atal'Hakkar.",al={"why was atal'ai exile banished","why is the exile in hinterlands","atal'ai exile backstory"}},{q="Are the artifacts brought to the exile dangerous?",a="The exile says the artifacts are harmless. The danger lies in the summoning ritual and whether Jammal'an has found the right fetish enchantment for it.",al={"are the artifacts harmful","fetish artifacts danger"}}},kw={"atal'ai exile","fel'zerul","hinterlands","jammal'an","stonard","summoning ritual","temple of atal'hakkar"},rel={"npc:fel-zerul","subzone:stonard","subzone:temple-of-atal-hakkar","zone:hinterlands"},m={start="Atal'ai Exile",["end"]="Fel'zerul",level="44",faction="Horde",id=1444},src={"Wowpedia: Return to Fel'Zerul"}}
E["quest:1450"] = {t="quest",n="Gryphon Master Talonaxe",z="hinterlands",s="Inside the Aerie Peak Aviary, flight assignments fall to Gryphon Master Talonaxe. Falstad Wildhammer sends you there after turning away someone who came for an old Explorers' League friend.",h="Inside the Aerie Peak Aviary, flight assignments fall to Gryphon Master Talonaxe.",sec={{t="Sent Away",b="Falstad Wildhammer has little patience for a visitor sent by an old Explorers' League member. He does not know who that friend once flew with, and flight assignments belong to the gryphon master. You can find Gryphon Master Talonaxe inside the Aerie Peak Aviary. Falstad has real work for anyone who stays nearby.",sp=0},{t="What Talonaxe Remembers",b="Gryphon Master Talonaxe remembers sending a gryphon rider to help Brohann Caskbelly. Talonaxe has long cared for the Explorers' League, for Talonaxe's father helped the first excavation team to find Uldaman. The rider was Rhapsody Shindigger, whom Talonaxe thought the best at the time.",sp=1}},faq={{q="Why does Falstad Wildhammer send you to Talonaxe?",a="Falstad Wildhammer does not know who the Explorers' League friend flew with. So he sends you to the gryphon master, who handles flight assignments.",al={"why see talonaxe","falstad sending away","who is talonaxe"}},{q="Where is Gryphon Master Talonaxe located?",a="Gryphon Master Talonaxe waits inside the Aerie Peak Aviary.",al={"where is talonaxe","talonaxe location","aerie peak aviary"}}},kw={"aerie peak","aviary","brohann caskbelly","explorers league","falstad wildhammer","gryphon master talonaxe","rhapsody shindigger","uldaman"},rel={"quest:1451","topic:explorers-league","subzone:uldaman","zone:hinterlands"},m={start="Falstad Wildhammer",["end"]="Gryphon Master Talonaxe",level="43",faction="Alliance",id=1450},src={"Wowpedia: Gryphon Master Talonaxe (quest)"}}
E["quest:1451"] = {t="quest",n="Rhapsody Shindigger",z="hinterlands",s="At the Aerie Peak Aviary, Talonaxe has news of a fallen flyer. Rhapsody Shindigger was once its finest flyer, but liquor cost Rhapsody the post. Now Rhapsody keeps a brewing camp east of the aviary, in the Hinterlands, Talonaxe has heard.",h="At the Aerie Peak Aviary, Talonaxe has news of a fallen flyer.",sec={{t="A Fallen Flyer",b="Gryphon Master Talonaxe says the aviary dwarves all enjoy a good ale. Rhapsody took to liquor as readily as a gryphon takes to the skies. No one could fly like Rhapsody, and Talonaxe still regrets the loss.\n\nThe trouble began when Rhapsody returned stumbling from a trip with Brohann. Things worsened quickly, and the aviary let Rhapsody go. Talonaxe’s last word is that Rhapsody now keeps a brew camp east of Aerie Peak.",sp=0}},faq={{q="Who sends you to find Rhapsody Shindigger?",a="Gryphon Master Talonaxe at the Aerie Peak Aviary sends you to find Rhapsody.",al={"who starts rhapsody shindigger","who gives rhapsody quest","where to start rhapsody"}},{q="Why was Rhapsody Shindigger let go from the aviary?",a="Rhapsody took to liquor as readily as a gryphon takes to the skies. Trouble began when Rhapsody returned stumbling from a flight with Brohann, then worsened quickly until the aviary let Rhapsody go.",al={"why was rhapsody fired","what happened to rhapsody","rhapsody shindigger backstory"}},{q="Where is Rhapsody now?",a="Talonaxe has heard that Rhapsody now keeps a brew camp east of the aviary, in the Hinterlands.",al={"where is rhapsody shindigger","rhapsody camp location","how to find rhapsody"}}},kw={"aerie peak","aviary","brohann","gryphon master talonaxe","hinterlands","rhapsody shindigger"},rel={"quest:1450","quest:1452","zone:hinterlands"},m={start="Gryphon Master Talonaxe",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1451},src={"Wowpedia: Rhapsody Shindigger (quest)"}}
E["quest:1452"] = {t="quest",n="Rhapsody's Kalimdor Kocktail",z="hinterlands",s="In the Hinterlands, Rhapsody Shindigger is ready to tell you what happened in the swamp, once he has a stiff drink. His Kalimdor Kocktail needs Roc gizzards from Tanaris and Groddoc and Ironfur livers from Feralas.",h="In the Hinterlands, Rhapsody Shindigger is ready to tell you what happened in the swamp, once he has a stiff...",sec={{t="A Stiff Drink",b="Rhapsody greets Brohann's messenger with a hiccup. The two shared quite an adventure, but Rhapsody will tell you what happened in the swamp only after a stiff drink. The tale is not pretty. He has a recipe in mind: the Kalimdor Kocktail. Once it is brewed, he promises to tell you everything.",sp=0},{t="Ingredients from Kalimdor",b="Rhapsody needs three Roc gizzards from Tanaris, three Groddoc livers from Feralas, and three Ironfur livers from Feralas. Even his finest malt cannot help him face the memory of that fateful flight over the swamp.",sp=0}},faq={{q="What does Rhapsody want for the Kalimdor Kocktail?",a="Rhapsody wants three Roc gizzards, three Groddoc livers, and three Ironfur livers for the Kalimdor Kocktail. He wants a stiff drink before telling you what happened in the swamp.",al={"why kocktail","why roc gizzards","why livers"}},{q="Where do the ingredients come from?",a="The Roc gizzards come from Tanaris. The Groddoc and Ironfur livers come from Feralas.",al={"where to find gizzards","cocktail ingredients location","where are groddocs"}},{q="Who sent you to Rhapsody Shindigger?",a="Brohann sent you to Rhapsody Shindigger, who calls Brohann a crazy fool. Before that, Gryphon Master Talonaxe told you where to find Rhapsody.",al={"who sent me to rhapsody","previous quest","brohan"}}},kw={"brohann","feralas","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard","tanaris"},rel={"quest:1451","quest:1469","zone:hinterlands","zone:feralas","zone:tanaris"},m={start="Rhapsody Shindigger",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1452,ri={"Groddoc Liver","Ironfur Liver","Roc Gizzard"}},src={"Rhapsody's Kalimdor Kocktail"}}
E["quest:1469"] = {t="quest",n="Rhapsody's Tale",z="hinterlands",s="After Rhapsody Shindigger gets his Kalimdor Kocktail, he tells of the flight with Brohann Caskbelly. He gives you an Atal'ai Tablet Fragment to take to Brohann in Stormwind.",h="After Rhapsody Shindigger gets his Kalimdor Kocktail, he tells of the flight with Brohann Caskbelly.",sec={{t="A Fragment for Brohann",b="Rhapsody Shindigger tells you what happened after the kocktail. Before the flight, he drank a whole keg of stout while Brohann followed him through the sky. Rhapsody kept a troll souvenir, an Atal'ai Tablet Fragment. Now he asks you to take it to Brohann Caskbelly in Stormwind.",sp=0},{t="Where the Flight Ended",b="Rhapsody saw no temple from the air. A little too tipsy, he fell from his mount and plunged into the water. The current pulled him down among creepy trolls, and he swam out fast with a souvenir. Brohann's temple lies below the water.",sp=1}},faq={{q="Who receives the Atal'ai Tablet Fragment?",a="Take the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.",al={"who do i give the fragment to","brohann location","where does tablet go"}},{q="What does Rhapsody remember of the flight with Brohann?",a="Before the flight, Rhapsody drank a whole keg of stout, then flew through the sky with Brohann following behind.",al={"why did rhapsody fly","brohann and rhapsody"}},{q="What came before this step?",a="Rhapsody's Kalimdor Kocktail came first. He would not tell the tale until the drink was made.",al={"previous quest","prereq rhapsody's tale"}}},kw={"atal'ai","brohann","caskbelly","fragment","hinterlands","rhapsody","shindigger","stormwind","tablet"},rel={"quest:1452","quest:1451","topic:stormwind-kingdom","topic:troll","zone:hinterlands"},m={start="Rhapsody Shindigger",["end"]="Brohann Caskbelly",level="43",faction="Alliance",id=1469},src={"Wowpedia: Rhapsody's Tale"}}
E["quest:2742"] = {t="quest",n="Rin'ji is Trapped!",z="hinterlands",s="At Quel'Danil Lodge, Rin'ji has lost an axe and is held captive. Rin'ji asks a passer-by for help escaping, offers something in return, and speaks of a secret at the Overlook Cliffs.",h="At Quel'Danil Lodge, Rin'ji has lost an axe and is held captive.",sec={{t="A Plea for Escape",b="At Quel'Danil Lodge, Rin'ji is frightened and held captive. The axe is gone, so Rin'ji begs a passer-by to help escape. Many dislike Rin'ji's kind. Still, Rin'ji offers something to a kind soul who helps and says a secret lies hidden at the Overlook Cliffs.",sp=0},{t="At the End of the Escape",b="A troll tablet bears strange markings. No one can make out what the writing says.",sp=1}},faq={{q="Who is Rin'ji?",a="Rin'ji is a troll who lost an axe and was captured at Quel'Danil Lodge in the Hinterlands. Rin'ji speaks of the self in the third person and begs a passer-by for help escaping.",al={"rinji","who is the troll in quel'danil","who is rin'ji"}},{q="Where is Rin'ji held captive?",a="Rin'ji is held captive at Quel'Danil Lodge in the Hinterlands.",al={"where is rin'ji","rinji location","quel'danil cage"}},{q="What does Rin'ji offer for help?",a="Rin'ji offers something to those who help and says a secret is hidden at the Overlook Cliffs.",al={"what is rin'ji's secret","rinji reward","what is at overlook cliffs"}}},kw={"captive","escort","hinterlands","overlook cliffs","quel'danil","rin'ji","tablet"},rel={"quest:2782","zone:hinterlands","topic:troll"},m={start="Rin'ji",["end"]="Rin'ji's Secret",level="47",faction="Horde",id=2742},src={"Wowpedia: Rin'ji is Trapped!"}}
E["quest:2782"] = {t="quest",n="Rin'ji's Secret",z="hinterlands",s="After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read. Oran Snakewrithe studies the Witherbark and may decipher it. He is known to live in the Magic Quarter of the Undercity.",h="After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read.",sec={{t="A Tablet Nobody Can Read",b="Witherbark troll markings cover the tablet, but what Rin'ji's secret is remains a mystery. It may be worth a great deal or nothing at all. A Witherbark troll in trouble might try anything to escape it.",sp=0},{t="A Scholar in the Undercity",b="Oran Snakewrithe is a well-known scholar of the Witherbark trolls. He is known to live in the Magic Quarter of the Undercity and may be able to read the tablet.",sp=0}},faq={{q="Where did this tablet come from?",a="The tablet is the secret Rin'ji hid at the Overlook Cliffs. You found it after helping Rin'ji escape from Quel'Danil Lodge.",al={"rinji tablet source","how do i get the tablet"}},{q="Who can read the markings on the tablet?",a="Oran Snakewrithe knows the Witherbark trolls well and may be able to decipher the markings.",al={"who can decipher the tablet","who reads witherbark markings"}},{q="Where is Oran Snakewrithe located?",a="Oran Snakewrithe is known to live in the Magic Quarter of the Undercity.",al={"oran snakewrithe location","where is oran"}},{q="Is the tablet valuable?",a="Nobody can say. The tablet may be worth a great deal or nothing at all, since a Witherbark troll in distress might try anything to escape trouble.",al={"what is rinji's secret","tablet meaning"}}},kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","tablet","undercity","witherbark"},rel={"quest:2742","zone:undercity","subzone:magic-quarter","zone:hinterlands","topic:troll"},m={start="Rin'ji's Secret",["end"]="Oran Snakewrithe",level="47",faction="Horde",id=2782},src={"Rin'ji's Secret (quest)"}}
E["quest:2877"] = {t="quest",n="Skulk Rock Clean-up",z="hinterlands",s="Sludges and oozes overrun the Horde's old positions around Skulk Rock. Fraggar Thundermantle at Aerie Peak wants them cleared, for the Wildhammers have plans for the ground.",h="Sludges and oozes overrun the Horde's old positions around Skulk Rock.",sec={{t="A Matter of Territory",b="The Wildhammers remember the past more than their brothers in Ironforge do. Fraggar Thundermantle says friends are made here by getting your hands dirty. The Horde left its positions around Skulk Rock in the Hinterlands, and sludges and oozes have overrun them. The Wildhammers have plans for that ground, but first the infestation must be thinned.",sp=0},{t="Clearing the Ground",b="Slay ten green sludges and ten jade oozes. Then return to Fraggar at Aerie Peak with your report.",sp=0}},faq={{q="Who is Fraggar Thundermantle?",a="Fraggar Thundermantle is a Wildhammer at Aerie Peak in the Hinterlands. He wants Skulk Rock cleared.",al={"who gives skulk rock clean up","fraggar thundermantle"}},{q="Why do the Wildhammers want Skulk Rock cleared?",a="The Horde left its positions around Skulk Rock, and sludges and oozes have overrun them. The Wildhammers have plans for the area, but first the infestation must be thinned.",al={"why kill the oozes","wildhammer plans skulk rock"}},{q="What creatures dwell at Skulk Rock?",a="Green sludges and jade oozes have overrun the old Horde positions at Skulk Rock.",al={"skulk rock mobs","what is at skulk rock"}},{q="Why does Fraggar bring up Ironforge?",a="Fraggar says the Wildhammers remember the past more than their brothers in Ironforge do. He says friends are made here by getting your hands dirty.",al={"wildhammer ironforge difference","fraggar ironforge"}}},kw={"aerie peak","fraggar thundermantle","green sludge","hinterlands","jade ooze","skulk rock","wildhammer"},rel={"zone:hinterlands","topic:horde"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="48",faction="Alliance",id=2877},src={"Wowpedia: Skulk Rock Clean-up"}}
E["quest:2880"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="At Aerie Peak, Fraggar Thundermantle asks you to bring him five necklaces from trolls in the Hinterlands.",h="At Aerie Peak, Fraggar Thundermantle asks you to bring him five necklaces from trolls in the Hinterlands.",sec={{t="Earning Wildhammer Regard",b="Fraggar Thundermantle trusts deeds over words. The Wildhammers answer to no Alliance, and anyone seeking their friendship must prove their worth first. Trolls roaming the Hinterlands hillsides sometimes wear tribal necklaces. Bring five to Fraggar at Aerie Peak, and you will have made a start.",sp=0}},faq={{q="Why does Fraggar Thundermantle want troll necklaces?",a="Fraggar judges people by their deeds, not their words. Five troll necklaces make a good beginning for anyone seeking Wildhammer friendship.",al={"why troll necklaces","troll necklace bounty purpose","why does fraggar want necklaces"}},{q="Are the Wildhammers part of the Alliance?",a="Fraggar says the Wildhammers are independent and answer to no Alliance. They judge people by their deeds.",al={"are wildhammers alliance","is aerie peak alliance","wildhammer allegiance"}},{q="Where can troll tribal necklaces be found?",a="Trolls roaming the Hinterlands hillsides sometimes carry tribal necklaces.",al={"where to get troll tribal necklace","troll necklace location","how to get troll necklaces"}},{q="Who do I return the necklaces to?",a="Bring the five necklaces to Fraggar Thundermantle at Aerie Peak.",al={"who gets troll necklaces","fraggar thundermantle turn in","where is fraggar thundermantle"}}},kw={"aerie peak","bounty","fraggar thundermantle","hinterlands","troll tribal necklace","trolls","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",faction="Alliance",id=2880,ri={"Troll Tribal Necklace"}},src={"Wowpedia: Troll Necklace Bounty"}}
E["quest:2881"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="For Fraggar Thundermantle, troll tribal necklaces still come in batches of five. The Wildhammer has already accepted one batch from you, and the offer remains open.",h="For Fraggar Thundermantle, troll tribal necklaces still come in batches of five.",sec={{t="A Standing Offer",b="Fraggar Thundermantle welcomes more troll tribal necklaces whenever you find them and choose to hand them over. He says the Wildhammers will fight for those who fight for them. Each batch must hold five necklaces.",sp=0},{t="Fraggar's Approval",b="Fraggar Thundermantle is pleased when you bring him the necklaces. To him, they prove you are willing to get your hands dirty, a quality the Wildhammers prize.",sp=1}},faq={{q="Who wants the troll tribal necklaces?",a="Fraggar Thundermantle speaks for the Wildhammers.",al={"who gives this bounty","fraggar thundermantle role","who takes the necklaces"}},{q="How many troll tribal necklaces are needed?",a="Five at a time. Fraggar counts a batch only when it holds five necklaces.",al={"necklace count","how many necklaces","bounty requirement"}},{q="Why does Fraggar Thundermantle collect these necklaces?",a="Fraggar treats the necklaces as proof that you are willing to fight for the Wildhammers. He says they will fight for those who do.",al={"why troll necklaces","wildhammer motive","purpose of bounty"}},{q="What came before this bounty?",a="You already completed the first Troll Necklace Bounty for Fraggar Thundermantle.",al={"prerequisite quest","previous step","prior bounty"}}},kw={"fraggar thundermantle","hinterlands","tribal necklace","troll necklace bounty","trolls","wildhammer"},rel={"quest:2880","zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",faction="Alliance",id=2881},src={"Classic quest text: Troll Necklace Bounty"}}
E["quest:2933"] = {t="quest",n="Venom Bottles",z="hinterlands",s="In the Hinterlands, Venom Bottles fill a Witherbark village. Their great number suggests the Witherbarks value the vile green venom, and an apothecary in nearby Tarren Mill may want a sample.",h="In the Hinterlands, Venom Bottles fill a Witherbark village.",sec={{t="A Toxic Discovery",b="Vile green venom fills bottles throughout the Witherbark village. There are many of them, suggesting the Witherbarks consider the venom important. An apothecary in Tarren Mill may want a sample to examine.",sp=0},{t="Lydon's Verdict",b="Apothecary Lydon has had no success with his experiments that day. He identifies the contents as venom drawn from some arachnoid creature, then asks where the venom came from.",sp=1}},faq={{q="Where are the venom bottles found?",a="The bottles are found in great numbers in a Witherbark village in the Hinterlands.",al={"venom bottle location","where to find venom bottles","witherbark venom"}},{q="Who is interested in the venom bottles?",a="An apothecary in Tarren Mill may want a sample. Apothecary Lydon is the one to see.",al={"who wants the venom","where to turn in venom bottle","tarren mill apothecary"}},{q="What is in the bottles?",a="The bottles hold vile green venom. Their great number suggests the Witherbarks value it highly.",al={"what is the venom","what is in the bottles"}}},kw={"apothecary lydon","arachnoid","hinterlands","tarren mill","troll venom","venom bottle","witherbark"},rel={"zone:hinterlands","subzone:tarren-mill","quest:2934"},m={start="Venom Bottle",["end"]="Apothecary Lydon",level="43",faction="Horde",id=2933},src={"Venom Bottles"}}
E["quest:2988"] = {t="quest",n="Witherbark Cages",z="hinterlands",s="At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon. Gryphon Master Talonaxe believes the trolls took the young gryphon.",h="At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon.",sec={{t="A Missing Heir",b="Gryphon Master Talonaxe asks you to find Sharpbeak, who went missing a few days ago while hunting with his parents. Talonaxe and the others believe the trolls took him. Three cages in the two Witherbark troll villages remain to be checked. Talonaxe awaits your findings.",sp=0},{t="Word From the Villages",b="Sharpbeak is not in the Witherbark villages. Talonaxe takes the news gravely. The young gryphon is meant to lead the next generation. Without him, the fleet would lose much of its strength and spirit.",sp=1}},faq={{q="Who is Sharpbeak?",a="Sharpbeak is Swiftwing's heir, and Talonaxe calls Swiftwing the mightiest gryphon. Sharpbeak went missing a few days ago while hunting with his parents.",al={"sharpbeak","who is the gryphon","swiftwing heir"}},{q="Why are the Witherbark trolls suspected?",a="Talonaxe and the others believe the Witherbark trolls took Sharpbeak. The cages in their two villages are the first places to search.",al={"why trolls","witherbark involvement","who took sharpbeak"}},{q="Where do I search for Sharpbeak?",a="Search the cages in the two Witherbark troll villages. Then return to Gryphon Master Talonaxe and tell him what you found.",al={"where are the cages","witherbark cages location","where to look for sharpbeak"}}},kw={"cages","gryphon","hinterlands","sharpbeak","swiftwing","talonaxe","trolls","witherbark"},rel={"quest:2989","quest:1450","zone:hinterlands","topic:troll","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="45",faction="Alliance",id=2988},src={"Wowpedia: Witherbark Cages"}}
E["quest:2989"] = {t="quest",n="The Altar of Zul",z="hinterlands",s="At the Altar of Zul, Talonaxe's search for Sharpbeak reaches the Vilebranch lands. Witherbark has no sign of the young gryphon, and Talonaxe fears the Vilebranch may hold him.",h="At the Altar of Zul, Talonaxe's search for Sharpbeak reaches the Vilebranch lands.",sec={{t="Another Tribe, Another Search",b="With no sign of Sharpbeak in the Witherbark cages, Gryphon Master Talonaxe suspects the Vilebranch trolls took him. So he sends you to search the top of the Altar of Zul, at the western edge of their lands. If they hold the gryphon child, Talonaxe fears what they may be doing to him.",sp=0},{t="Word From the Altar",b="Sharpbeak is not at the altar. Talonaxe calls that bad news, but good as well. The Vilebranch are known to carry out sacrifices, and he is relieved the gryphon was not found there. He thanks you for your aid and says a greater undertaking lies ahead.",sp=1}},faq={{q="Why does Gryphon Master Talonaxe send you to the Altar of Zul?",a="The Witherbark trolls do not have Sharpbeak, so Talonaxe suspects the Vilebranch may have taken him.",al={"why altar of zul","altar of zul reason","why go to altar of zul"}},{q="Where is the Altar of Zul located?",a="The Altar of Zul lies at the western edge of Vilebranch lands in the Hinterlands. You are to search its top.",al={"altar of zul location","where is altar of zul"}},{q="Who is Sharpbeak?",a="Sharpbeak is Swiftwing's heir, the gryphon child Talonaxe has searched for since he went missing.",al={"who is sharpbeak","sharpbeak lore"}},{q="Why is Talonaxe worried about the Vilebranch trolls?",a="Talonaxe fears what the Vilebranch trolls may be doing to Sharpbeak if they hold him.",al={"why are vilebranch dangerous","what do vilebranch do"}}},kw={"altar of zul","gryphon master talonaxe","hinterlands","sharpbeak","vilebranch","witherbark"},rel={"quest:1450","quest:2988","zone:hinterlands","topic:troll","quest:2992","quest:2993","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="48",faction="Alliance",id=2989},src={"Wowpedia: The Altar of Zul (quest)"}}
E["quest:2990"] = {t="quest",n="Thadius Grimshade",z="hinterlands",s="At Nethergarde Keep, Talonaxe sends you to Thadius Grimshade with a feather from Sharpbeak's nest.",h="At Nethergarde Keep, Talonaxe sends you to Thadius Grimshade with a feather from Sharpbeak's nest.",sec={{t="A Plea to a Diviner",b="Years ago, Thadius Grimshade left Aerie Peak to seek darker knowledge. Yet Talonaxe says he remains a Wildhammer at heart. He hopes Thadius can use divining magic and Sharpbeak's feather to find the gryphon child. Thadius lives in the mage tower at Nethergarde Keep, in the Blasted Lands.",sp=0},{t="The Diviner's Welcome",b="Thadius Grimshade welcomes you as someone bearing a gift. He recognizes the feather as belonging to a fine gryphon, one meant for great things if he grows up unharmed. Then Thadius asks you to listen closely.",sp=1}},faq={{q="Who is Thadius Grimshade?",a="Thadius Grimshade left Aerie Peak years ago to seek darker knowledge. Talonaxe says he remains a Wildhammer at heart.",al={"thadius grimshade lore","who is thadius"}},{q="Why do you need Sharpbeak's feather?",a="Sharpbeak's feather came from the nest where he sleeps. Talonaxe hopes Thadius can use divining magic on it to find the young gryphon.",al={"why sharpbeak feather","feather purpose"}},{q="Where is Thadius Grimshade located?",a="Thadius Grimshade lives in the mage tower at Nethergarde Keep, in the Blasted Lands.",al={"thadius grimshade location","where is thadius"}}},kw={"aerie peak","blasted lands","divination","gryphon","nethergarde keep","sharpbeak","talonaxe","thadius grimshade"},rel={"npc:thadius-grimshade","quest:1450","subzone:nethergarde-keep","zone:blastedlands","zone:hinterlands","quest:2989","quest:2992","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Thadius Grimshade",level="47",faction="Alliance",id=2990},src={"Thadius Grimshade (quest)"}}
E["quest:2994"] = {t="quest",n="Saving Sharpbeak",z="hinterlands",s="At Jintha'Alor, Sharpbeak waits in a cage deep in Vilebranch territory. Gryphon Master Talonaxe sends you to free him, and Vile Priestess Hexx holds the key.",h="At Jintha'Alor, Sharpbeak waits in a cage deep in Vilebranch territory.",sec={{t="Up Jintha'Alor",b="After Thadius Grimshade's divination, you report to Talonaxe. Now the path to Sharpbeak is clear. Jintha'Alor lies at the heart of Vilebranch territory, and you fight your way to its summit. Vile Priestess Hexx holds the key to Sharpbeak's cage. Take it from her, then find the cage and free the gryphon.",sp=0},{t="Talonaxe's Thanks",b="Swiftwind and Keenclaw have brought their child home, and they cannot stop fussing over him. The sight leaves Talonaxe misty-eyed. He says the debt cannot be repaid. Aerie Peak's gryphons and riders will sing your name for a long time.",sp=1}},faq={{q="Who sends you to rescue Sharpbeak?",a="Gryphon Master Talonaxe sends you to rescue Sharpbeak after Thadius Grimshade's divination reveals where the gryphon is held.",al={"who gives saving sharpbeak","sharpbeak questgiver","where do i start saving sharpbeak"}},{q="Where is Sharpbeak being held?",a="Sharpbeak is caged at the summit of Jintha'Alor, in Vilebranch territory in the Hinterlands.",al={"where is sharpbeak","sharpbeak location","where is sharpbeak cage"}},{q="Who holds the key to Sharpbeak's cage?",a="Vile Priestess Hexx has it.",al={"who drops sharpbeak key","where is hexx key","vile priestess hexx key"}}},kw={"aerie peak","gryphon master talonaxe","hinterlands","jintha'alor","saving sharpbeak","sharpbeak","vile priestess hexx","vilebranch"},rel={"quest:2993","quest:2992","zone:hinterlands","npc:thadius-grimshade","quest:2989","quest:2988"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="51",faction="Alliance",id=2994},src={"Wowpedia: Saving Sharpbeak"}}
E["quest:4297"] = {t="quest",n="Food for Baby",z="hinterlands",s="Agnar Beastamer will care for your egg until it hatches. Sprite darters eat meat and vegetation, and their young favor raw, juicy flanks. Agnar wants Silvermane stalker flanks for the hatchling.",h="Agnar Beastamer will care for your egg until it hatches.",sec={{t="A Hatchling's First Meal",b="Agnar Beastamer says sprite darters eat meat and vegetation. Their young favor raw, juicy flanks. Agnar will care for the egg until it hatches and wants Silvermane stalker flanks for the hatchling. Without a good first meal, the newborn might not live through its first week.",sp=0},{t="Elune's Plan",b="Agnar never learned why sprite darters eat meat. Agnar knows only that it is tied to Elune’s plan for the elves. Perhaps they were meant to be protectors, Agnar wonders, but cannot say for sure. Agnar also admits to being jealous that you got the egg.",sp=0},{t="Back with the Flanks",b="When you return with the flanks, Agnar judges them good enough. The egg looks just about ready to hatch. Agnar teases that you will soon be a mother or father, though you did not expect that kind of responsibility.",sp=1}},faq={{q="What does a sprite darter eat?",a="Sprite darters eat meat and vegetation. Agnar Beastamer says raw, juicy flanks suit the young ones.",al={"sprite darter diet","what do sprite darters eat","sprite dragon food"}},{q="Where is Agnar Beastamer caring for the egg?",a="Agnar cares for the egg in the Hinterlands, where the meat is brought.",al={"agnar beastamer location","where is agnar"}},{q="What meat does Agnar want?",a="Agnar wants five Silvermane stalker flanks for the hatchling.",al={"what meat to get","food for baby meat","stalker flanks"}},{q="How does Elune connect to sprite darters?",a="Agnar never learned why darters eat meat, only that it is tied to Elune’s plan for the elves. Agnar wonders whether they were meant to be protectors.",al={"elune sprite darter","why meat elune"}},{q="What happens if the hatchling has no good first meal?",a="Without a good first meal, the hatchling might not live through its first week, Agnar warns.",al={"hatchling no food","will the baby survive"}}},kw={"agnar beastamer","egg","elune","flanks","hinterlands","omnivore","silvermane stalker","sprite darter"},rel={"quest:3843","quest:4298","quest:2969","npc:sprite-darter","topic:elune","zone:feralas"},m={start="Agnar Beastamer",["end"]="Agnar Beastamer",level="47",faction="Alliance",id=4297,ri={"Silvermane Stalker Flank"}},src={"Food for Baby"}}
E["quest:4298"] = {t="quest",n="Becoming a Parent",z="hinterlands",s="In the Hinterlands, Agnar Beastamer has news: the egg is further along than he expected. He wants to speak with you.",h="In the Hinterlands, Agnar Beastamer has news: the egg is further along than he expected.",sec={{t="Sooner Than Expected",b="The egg has advanced further than Agnar Beastamer expected. You have brought food for the hatchling. Now speak with Agnar in the Hinterlands.",sp=0},{t="A Parent, of a Sort",b="Agnar Beastamer gives you the egg so it can bond with you and look to you as its parent. He congratulates you on becoming a parent, of a sort.",sp=1}},faq={{q="Who has news about the egg?",a="Agnar Beastamer has news about the egg. He has been looking after it in the Hinterlands.",al={"who starts becoming a parent","becoming a parent quest giver","agnar beastamer quest"}},{q="Where do I find Agnar Beastamer?",a="Agnar Beastamer is in the Hinterlands.",al={"becoming a parent location","where is agnar beastamer"}},{q="What came before this step?",a="Before this, you gathered meat for the hatchling in Food for Baby.",al={"becoming a parent prerequisite","previous quest becoming a parent"}}},kw={"agnar beastamer","becoming a parent","egg","food for baby","freedom for all creatures","hinterlands","pet"},rel={"quest:4297","quest:2969","zone:hinterlands","zone:feralas"},m={start="Agnar Beastamer",["end"]="Agnar Beastamer",level="48",faction="Alliance",id=4298},src={"Becoming a Parent"}}
E["quest:485"] = {t="quest",n="Find OOX-09/HL!",z="hinterlands",s="Near Skulk Rock, a homing robot lies crashed in the Hinterlands. Its gnomish maker, Oglethorpe Obnoticus, calls through a metal egg and asks you to carry a beacon to the wreck.",h="Near Skulk Rock, a homing robot lies crashed in the Hinterlands.",sec={{t="A Crackling Call",b="Turn the knob on the strange metal egg, and a gnomish device opens. A crackling voice gives the name Oglethorpe Obnoticus. His homing robot has crashed, and he has worked out where it came down: where the river begins, near Skulk Rock. Carry the beacon there.",sp=0},{t="The Wreckage at the River",b="At the river's head, you find wreckage shaped like a robotic chicken. Oglethorpe Obnoticus confirms that it is his homing robot. It needs a jump start before it can return to Booty Bay for repairs. Place the beacon inside.",sp=0}},faq={{q="Who is speaking through the distress beacon?",a="A gnome named Oglethorpe Obnoticus is speaking through the distress beacon. His homing robot has crashed in the Hinterlands.",al={"who made the beacon","who is oglethorpe","who is speaking"}},{q="Where did the robot crash?",a="The robot crashed where the river begins, near Skulk Rock in the Hinterlands.",al={"where is the robot","oox 09 hl location","where to find robot"}},{q="What does the homing robot look like?",a="The wreck looks like a robotic chicken.",al={"what is the robot","chicken robot","what does oox look like"}},{q="What is the beacon for?",a="The beacon goes inside the robot to give it the jump start it needs to return to Booty Bay for repairs.",al={"how to activate robot","what to do with the beacon","how to complete find oox-09/hl"}}},kw={"booty bay","distress beacon","hinterlands","homing robot","oglethorpe obnoticus","oox-09/hl","skulk rock"},rel={"quest:836","subzone:booty-bay","zone:hinterlands"},m={start="OOX-09/HL Distress Beacon",["end"]="Homing Robot OOX-09/HL",level="48",faction="Neutral",id=485},src={"Wowpedia: Find OOX-09/HL!"}}
E["quest:77"] = {t="quest",n="A Sticky Situation",z="hinterlands",s="Dran Droffers seeks the original packaging for Hinterlands Honey Ripple. Gilveradin Sunchaser has it and asks for two extra bottles; ten bottles wait in crates around the abandoned Horde base near Skulk Rock.",h="Dran Droffers seeks the original packaging for Hinterlands Honey Ripple.",sec={{t="A Matter of Packaging",b="Dran Droffers seeks Hinterlands Honey Ripple, and Gilveradin Sunchaser has its original packaging. Gilveradin offers to help in return for two extra bottles. Gather ten bottles and bring them back to the camp.",sp=0},{t="Ruins of Skulk Rock",b="Crates of Hinterlands Honey Ripple are scattered around the abandoned Horde base near Skulk Rock. Foul slimes and oozes cling to the ruins. Rumor says a master ooze leads them.",sp=0}},faq={{q="Who wants the Hinterlands Honey Ripple packaged?",a="Dran Droffers seeks Hinterlands Honey Ripple. Gilveradin Sunchaser has its original packaging, meant for Malton's father.",al={"who needs the ripple","dran droffers ripple","who is the packaging for"}},{q="What does Gilveradin charge for the packaging?",a="Gilveradin asks for two extra bottles of the ripple as his fee. Ten bottles are in the crates.",al={"why 10 bottles","gilveradin fee","why so much ripple"}},{q="Where are the crates of Hinterlands Honey Ripple kept?",a="The crates are around the abandoned Horde base near Skulk Rock in the Hinterlands.",al={"ripple location","where is the honey ripple","skulk rock crates"}},{q="What is at the abandoned camp at Skulk Rock?",a="Foul slimes and oozes cling to the ruins, and rumor says a master ooze leads them.",al={"skulk rock monsters","what is at skulk rock","skulk rock oozes"}}},kw={"dran droffers","gilveradin sunchaser","hinterlands","hinterlands honey ripple","oozes","skulk rock","slimes"},rel={"zone:hinterlands","topic:horde"},m={start="Gilveradin Sunchaser",["end"]="Gilveradin Sunchaser",level="48",faction="Horde",id=77,ri={"Hinterlands Honey Ripple"}},src={"Wowpedia: A Sticky Situation"}}
E["quest:7815"] = {t="quest",n="Snapjaws, Mon!",z="hinterlands",s="In Revantusk Village, Katoom the Angler asks you to deal with saltwater snapjaws ruining his fishing. He wants fifteen turtles killed.",h="In Revantusk Village, Katoom the Angler asks you to deal with saltwater snapjaws ruining his fishing.",sec={{t="Trouble on the Line",b="Katoom the Angler asks you to help him and his neighbours in Revantusk Village. Saltwater snapjaws may look harmless, but they make fishing hard. One tears his line and steals his bait before he can fish for five minutes. Katoom wants you to kill fifteen of the turtles.",sp=0}},faq={{q="Who asks you to hunt the turtles?",a="Katoom the Angler, a fisher in Revantusk Village in the Hinterlands, asks you to hunt the turtles.",al={"who gives snapjaws mon","snapjaws mon quest giver","katoom the angler"}},{q="Why does Katoom want the saltwater snapjaws killed?",a="Katoom says the saltwater snapjaws tear his fishing line and steal his bait. He can scarcely fish for five minutes before one interrupts him.",al={"why kill snapjaws","turtle nuisance","why kill turtles revantusk"}},{q="How many snapjaws need to be slain?",a="You need to kill fifteen saltwater snapjaw turtles.",al={"how many turtles","snapjaw count","snapjaws mon count"}}},kw={"angler","bait","fishing","hinterlands","katoom","revantusk","snapjaws","turtles"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="50",faction="Horde",id=7815},src={"Classic quest text: Snapjaws, Mon!"}}
E["quest:7816"] = {t="quest",n="Gammerita, Mon!",z="hinterlands",s="At Revantusk Village, Katoom the Angler wants his best lure back from Gammerita, Mon!, who leads the saltwater snapjaws. Find her and recover it.",h="At Revantusk Village, Katoom the Angler wants his best lure back from Gammerita, Mon!, who leads the...",sec={{t="A Thief Among the Turtles",b="Katoom says Gammerita, Mon! is no ordinary turtle. She leads the saltwater snapjaws, and he calls her a thief. She snapped his best lure off his line. Since then, the fish have not bitten as they once did.",sp=0},{t="Getting the Lure Back",b="Katoom wants you to find Gammerita, Mon! and recover his lure from her stomach. She stays along the coast among the other turtles.",sp=0},{t="Katoom's Hopes",b="With his lure back and fewer snapjaws about, Katoom expects the fish to come in by the heap.",sp=1}},faq={{q="Who is Katoom the Angler?",a="Katoom the Angler fishes at Revantusk Village in the Hinterlands. He asks you to hunt Gammerita.",al={"who is katoom","katoom revantusk","katoom location"}},{q="What is Gammerita?",a="Gammerita is no ordinary turtle. She leads the saltwater snapjaws, and Katoom calls her a thief.",al={"who is gammerita","what is gammerita","gammerita turtle"}},{q="Why does Katoom want Gammerita dead?",a="Gammerita snapped Katoom's best lure off his line, and the fish have not bitten as they once did. He wants it back from her stomach.",al={"why kill gammerita","what did gammerita steal","katoom motive"}},{q="Where can Gammerita be found?",a="Gammerita stays on the coast among the other saltwater snapjaw turtles.",al={"where is gammerita","gammerita location","find gammerita"}}},kw={"angler","gammerita","hinterlands","katoom","lure","revantusk","snapjaw","turtle"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="48",faction="Horde",id=7816},src={"Classic quest text: Gammerita, Mon!"}}
E["quest:7828"] = {t="quest",n="Stalking the Stalkers",z="hinterlands",s="In Revantusk, Huntsman Markhor names the wolves threatening the village's hunters. He asks you to turn the hunt on them.",h="In Revantusk, Huntsman Markhor names the wolves threatening the village's hunters.",sec={{t="Wolves in Hiding",b="The Hinterlands wilds have already claimed many trolls. Markhor counts Silvermane wolves among the greatest dangers to Revantusk's hunters. They hide among bushes and in the lay of the land, then pounce when the moment is right. He urges you to think as a Silvermane does and hunt the hunters. Every one must be put down.",sp=0},{t="What Markhor Asks",b="Markhor asks you to kill fifteen Silvermane Stalkers and fifteen Silvermane Howlers. They lurk in the Hinterlands wilds.",sp=0},{t="Revantusk's Thanks",b="When the hunt is done, Markhor thanks you for what you have given the Revantusk.",sp=1}},faq={{q="Who asks for the wolves to be hunted?",a="Huntsman Markhor, of Revantusk in the Hinterlands, asks you to hunt the wolves.",al={"who gives stalking the stalkers","quest giver stalking the stalkers","markhor quest"}},{q="Why are the Silvermane wolves such a threat?",a="Silvermane wolves hide among bushes and the lay of the land, then strike when the chance comes. Markhor ranks them among the greatest dangers to Revantusk's hunters, and many trolls have already been lost in the wilds.",al={"why kill silvermane wolves","silvermane wolf threat","why cull wolves hinterlands"}},{q="Which wolves need to be culled?",a="You are asked to hunt fifteen Silvermane Stalkers and fifteen Silvermane Howlers.",al={"what wolves to kill","stalking the stalkers targets","wolf types hinterlands"}},{q="Where are these wolves found?",a="The wolves lurk in the Hinterlands wilds.",al={"where are silvermane wolves","silvermane stalker location","silvermane howler location"}}},kw={"hinterlands wolves","huntsman markhor","revantusk","revantusk village","silvermane howler","silvermane stalker","stalking the stalkers"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",faction="Horde",id=7828},src={"Classic quest text: Stalking the Stalkers"}}
E["quest:7829"] = {t="quest",n="Hunt the Savages",z="hinterlands",s="In the Hinterlands, Huntsman Markhor sends you to hunt savage owlbeasts. He asks you to bring down twenty.",h="In the Hinterlands, Huntsman Markhor sends you to hunt savage owlbeasts.",sec={{t="Claws and Beaks",b="Huntsman Markhor warns that savage owlbeasts are among the Hinterlands' most ornery creatures. Their claws and beaks have cost Revantusk many good warriors. He wants every owlbeast you see killed, until you can bear no more bloodshed. Then he will weigh and judge your contribution. Twenty must fall.",sp=0},{t="Clearing the Mind",b="Markhor counsels you to clear your mind of unclean thoughts and join with the wild. Savage owlbeasts roam the Hinterlands wilds.",sp=0},{t="Markhor's Judgment",b="After the hunt, Huntsman Markhor names you a worthy friend to the Revantusk.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor, a huntsman from the village of Revantusk in the Hinterlands, offers the hunt.",al={"who gives hunt the savages","hunt the savages quest giver","huntsman markhor quest"}},{q="Why does Markhor want the savage owlbeasts killed?",a="Markhor calls savage owlbeasts ornery. Their claws and beaks have cost Revantusk many good warriors.",al={"why kill savage owlbeasts","reason for hunting owlbeasts","why hunt the savages"}},{q="Where can the savage owlbeasts be found?",a="Markhor says savage owlbeasts roam the Hinterlands wilds.",al={"savage owlbeast location","where are savage owlbeasts","owlbeasts in hinterlands"}},{q="How many savage owlbeasts must be slain?",a="Twenty savage owlbeasts must fall.",al={"how many owlbeasts to kill","hunt the savages requirement"}}},kw={"hinterlands","hunt the savages","huntsman markhor","owlbeasts","revantusk","revantusk village","savage owlbeast"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",faction="Horde",id=7829},src={"Classic quest text: Hunt the Savages"}}
E["quest:7830"] = {t="quest",n="Avenging the Fallen",z="hinterlands",s="At Revantusk Village, Markhor turns his anger toward the Skylords. He asks you to slay a Razorbeak Skylord and bring him its plume.",h="At Revantusk Village, Markhor turns his anger toward the Skylords.",sec={{t="Slaying the Skylords",b="Huntsman Markhor of Revantusk Village resents the Wildhammer for training gryphons to slay trolls. He promises justice for the trolls, but first he wants you to strike at the Skylords, the Hinterlands' elder gryphons.\n\nSlay a Razorbeak Skylord and bring its plume back to Markhor. This rare breed lives in the wilds of the Hinterlands. Markhor blames it for breeding murderous young.",sp=0},{t="The Plume Examined",b="Markhor studies the plume and wonders how many hunters the beast devoured before your hand brought it justice.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor offers the hunt at Revantusk Village in the Hinterlands.",al={"quest giver","who gives avenging the fallen","markhor location"}},{q="Why does Huntsman Markhor want a Skylord slain?",a="Markhor says the Wildhammer train gryphons to slay trolls. He wants the region's elder gryphons, the Skylords, eradicated, and blames the rare Razorbeak Skylord for breeding murderous young.",al={"why kill razorbeak skylord","why kill skylord","why hunt gryphons"}},{q="Where can a Razorbeak Skylord be found?",a="Markhor says the rare Razorbeak Skylord keeps to the wilds of the Hinterlands.",al={"skylord location","where is razorbeak skylord","skylord plume location"}},{q="What must be brought back to Markhor?",a="The plume of a Razorbeak Skylord, which means slaying one first.",al={"what item do i need","avenging the fallen objective","skylord drop"}}},kw={"avenging the fallen","gryphon","hinterlands","huntsman markhor","razorbeak skylord","revantusk village","skylord plume","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",faction="Horde",id=7830,ri={"Skylord Plume"}},src={"Wowpedia: Avenging the Fallen"}}
E["quest:7839"] = {t="quest",n="Vilebranch Hooligans",z="hinterlands",s="In Revantusk Village, Smith Slagtree seeks tools stolen by Vilebranch trolls. A kind-hearted gnome gave him the set after saving his life when he was a young orc.",h="In Revantusk Village, Smith Slagtree seeks tools stolen by Vilebranch trolls.",sec={{t="A Gift From a Gnome",b="Vilebranch trolls took Smith Slagtree's tools when they invaded Revantusk Village. He has spares, but the stolen set came from a kind-hearted gnome who saved his life when he was a young orc. The gift means the world to Slagtree, so he asks you to recover it.",sp=0},{t="Where the Tools Were Seen",b="Markhor saw the tools near the temples of Agol'watha and Shaol'watha in the northeast of the Hinterlands. Slagtree also says to check Skulk Rock. The Vilebranch trolls there are ruthless and murderous.",sp=0}},faq={{q="Why are these stolen tools so important to Smith Slagtree?",a="A kind-hearted gnome gave the tools to Slagtree after saving his life when he was a young orc. Slagtree has spares, but says the gifted set means the world to him.",al={"why does slagtree care about his tools","slagtree lost tools lore","why are slagtrees tools special"}},{q="Who stole the tools from Revantusk Village?",a="Vilebranch trolls stole Smith Slagtree's tools during their invasion of Revantusk Village.",al={"who took the tools","who stole slagtrees tools"}},{q="Where were the missing tools taken?",a="Near the temples of Agol'watha and Shaol'watha, in the northeast of the Hinterlands, where Markhor saw them. Slagtree also points to Skulk Rock.",al={"where are slagtrees tools","where to find the tools","slagtree tool location"}},{q="Who reported seeing the tools after the raid?",a="Markhor told Smith Slagtree where the tools had been seen.",al={"who saw the tools","who reported the stolen tools"}}},kw={"agol'watha","hinterlands","markhor","revantusk village","shaol'watha","skulk rock","slagtree's lost tools","smith slagtree","vilebranch"},rel={"zone:hinterlands","topic:troll"},m={start="Smith Slagtree",["end"]="Smith Slagtree",level="48",faction="Horde",id=7839,ri={"Slagtree's Lost Tools"}},src={"Wowpedia: Vilebranch Hooligans"}}
E["quest:7840"] = {t="quest",n="Lard Lost His Lunch",z="hinterlands",s="In the Hinterlands, Lard has run to Revantusk and left the picnic lunch behind. A Vilebranch struck Lard at a private picnic, and now Lard asks you to fetch the food from an island to the north.",h="In the Hinterlands, Lard has run to Revantusk and left the picnic lunch behind.",sec={{t="A Picnic Interrupted",b="A Vilebranch struck Lard with a big stick at a secret picnic spot. By Lard's account, the troll was ugly and mean. Lard fled to Revantusk, leaving the lunch behind and fearing a return.",sp=0},{t="The Island Northward",b="Lard's picnic spot lies on an island to the north. Lard hopes you will find the lunch and bring it back. Take care around the Vilebranch trolls.",sp=0},{t="Lard's Thanks",b="Lard's lunch is a huge haunch of meat. Lard wolfs it down, thanks you, and promises a special picnic basket for your help.",sp=1}},faq={{q="Who is Lard?",a="Lard lives in Revantusk in the Hinterlands. Hungry and frightened, Lard fled after a Vilebranch struck Lard with a big stick.",al={"lard hinterlands","who is lard","lard revantusk"}},{q="Where did Lard lose his lunch?",a="Lard left the lunch at a secret picnic spot on an island to the north.",al={"where is lards lunch","lard picnic spot","lards secret spot"}},{q="Why did Lard leave his food behind?",a="A Vilebranch struck Lard with a big stick during the picnic. Lard ran back to Revantusk without the lunch.",al={"why did lard run","who attacked lard"}},{q="What should you watch out for on the island?",a="Lard names the Vilebranch trolls as a danger on the island.",al={"vilebranch on island","dangers lards island"}}},kw={"hinterlands","island","lard","lunch","picnic","revantusk village","vilebranch"},rel={"zone:hinterlands"},m={start="Lard",["end"]="Lard",level="49",faction="Horde",id=7840},src={"Classic quest text: Lard Lost His Lunch"}}
E["quest:7841"] = {t="quest",n="Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko wants a message carried to the Wildhammer dwarves. Their new allies include the high elves, and Otho wants his warning written in the blood of the Highvale high elves at Quel'Danil Lodge.",h="At Revantusk Village, Otho Moji'ko wants a message carried to the Wildhammer dwarves.",sec={{t="A Message in Blood",b="The Wildhammer are making alliances with the trolls' enemies, and now the high elves stand with them. Otho Moji'ko spits at the thought. He wants the dwarves warned in the blood of their new friends. Slaughter every Highvale high elf you find and leave the bodies as a warning.\n\nHighvale Outrunners, Scouts, Marksmen and Rangers gather at Quel'Danil Lodge, in the northwest of the Hinterlands.",sp=0},{t="Word at Revantusk Village",b="When you return to Revantusk Village, Otho declares that the Revantusk are making new alliances too. He praises your work.",sp=1}},faq={{q="Who offers this quest?",a="Otho Moji'ko offers it from Revantusk Village.",al={"who gives message to the wildhammer","otho mojiko quest"}},{q="Where are the Highvale high elves located?",a="The Highvale high elves gather at Quel'Danil Lodge, in the northwest of the Hinterlands.",al={"quel danil lodge location","where are highvale elves","where to find highvale scouts"}},{q="Why does Otho Moji'ko want the high elves attacked?",a="Otho says the Wildhammer are striking deals with the trolls' enemies, and now they are working with the high elves. He wants a message carried to the Wildhammer dwarves, written in the blood of the high elves.",al={"why attack quel danil","why kill high elves hinterlands"}},{q="Which Highvale elves does Otho want slaughtered?",a="Otho wants the Highvale Outrunners, Scouts, Marksmen and Rangers at Quel'Danil Lodge slaughtered.",al={"which highvale elves","highvale marksman","highvale ranger"}}},kw={"highvale","hinterlands","message to the wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},rel={"zone:hinterlands","topic:troll","quest:7842","quest:7843"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7841},src={"Wowpedia: Message to the Wildhammer"}}
E["quest:7842"] = {t="quest",n="Another Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko sends another message to the Wildhammer. He sees their bond with gryphons as close as a troll and a mate, and means to turn it against them.",h="At Revantusk Village, Otho Moji'ko sends another message to the Wildhammer.",sec={{t="A Message of Feathers",b="After the Highvale high elves, Otho Moji'ko has another message for the Wildhammer. Their closeness with gryphons disgusts him, but he sees a use for it. Kill the gryphons you meet across the Hinterlands and gather their Long Elegant Feathers. Gryphons live in every region there. Otho will make his final message from the feathers.",sp=0},{t="Otho's Pleasure",b="Otho expects his final message to frighten the Wildhammer away or make them furious. He delights that only one step remains before they learn trolls cannot be crossed.",sp=1}},faq={{q="Who gives this quest?",a="Otho Moji'ko gives the message from Revantusk Village.",al={"who gives another message to the wildhammer","another message questgiver","otho mojiko"}},{q="Why does Otho Moji'ko want gryphon feathers?",a="Otho says the Wildhammer and their gryphons are as close as a troll and a mate. He means to use that bond against them, and make his final message from the feathers.",al={"why gryphon feathers","why kill gryphons hinterlands"}},{q="Where can gryphons be found?",a="Gryphons live in every region of the Hinterlands.",al={"gryphon locations hinterlands","where are hinterlands gryphons"}},{q="What came before this message?",a="This follows Message to the Wildhammer, in which Otho had Highvale high elves slaughtered as a warning to the dwarves.",al={"what comes before another message to the wildhammer","message to the wildhammer chain"}}},kw={"gryphon","hinterlands","long elegant feather","otho moji'ko","revantusk village","wildhammer"},rel={"quest:7841","quest:7843","zone:hinterlands","topic:troll"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7842},src={"Wowpedia: Another Message to the Wildhammer"}}
E["quest:7843"] = {t="quest",n="The Final Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko sends you west with a blood-soaked spear bound in gryphon feathers. The Wildhammer dwarves will find it planted beside the well at Aerie Peak's heart.",h="At Revantusk Village, Otho Moji'ko sends you west with a blood-soaked spear bound in gryphon feathers.",sec={{t="A Spear for Aerie Peak",b="After Another Message to the Wildhammer, Otho Moji'ko gives you a spear soaked in blood and bound with gryphon feathers. Carry it west to Aerie Peak and plant it beside the well at the town's heart. The Wildhammer dwarves will see that the trolls mean business. Furious dwarves and rowdy Alliance folk await you there, and Otho hopes you return alive.",sp=0},{t="Otho's Hope",b="Otho wonders how the dwarves will react when they see the spear. He wishes he could have seen their faces. Are they packing their bags to leave town? For carrying out the deed, Otho promises you the big mojo.",sp=1}},faq={{q="Who sends you to plant the spear?",a="Otho Moji'ko sends you from Revantusk Village.",al={"quest giver","who gives the quest","otho mojiko"}},{q="Where must the spear be planted?",a="Plant the spear beside the well at the heart of Aerie Peak, in the west of the Hinterlands.",al={"spear location","where do i place the spear","aerie peak well"}},{q="What is the final message made of?",a="The final message is a spear soaked in blood and bound with gryphon feathers.",al={"what is the spear","gryphon feathers spear","the final message item"}},{q="What came before this in the chain?",a="Another Message to the Wildhammer came first. Otho called for gryphon feathers to make this final message.",al={"previous quest","prerequisites","wildhammer message chain"}}},kw={"aerie peak","gryphon feathers","hinterlands","otho moji'ko","revantusk village","spear","wildhammer"},rel={"quest:7842","quest:7841","zone:hinterlands","topic:troll","topic:alliance"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="50",faction="Horde",id=7843},src={"Wowpedia: The Final Message to the Wildhammer"}}
E["quest:7844"] = {t="quest",n="Cannibalistic Cousins",z="hinterlands",s="In the Hinterlands, Mystic Yayo'jin asks you to strike at the Vilebranch near their temples. She calls them a depraved lot who prey on other trolls and humanoids. With Zul'jin away, the Revantusk are left to their own devices.",h="In the Hinterlands, Mystic Yayo'jin asks you to strike at the Vilebranch near their temples.",sec={{t="Three Tribes, One Land",b="Three troll tribes share the Hinterlands, though Mystic Yayo'jin says little binds them. The Vilebranch prey on other trolls and humanoids. Zul'jin could wipe them out with ease, but he is away. So the Revantusk are left to their own devices.",sp=0},{t="Where the Vilebranch Gather",b="Yayo'jin asks you to destroy the Vilebranch Scalpers and Soothsayers near the Shaol'watha and Agol'watha temples. The temples lie in the Hinterlands' north by northeast.",sp=0},{t="Yayo'jin's Praise",b="When you return, Yayo'jin says even Zul'jin could not have done better.",sp=1}},faq={{q="Who offers this quest?",a="Mystic Yayo'jin offers it from Revantusk Village.",al={"cannibalistic cousins quest giver","who gives cannibalistic cousins","mystic yayojin"}},{q="Why does Yayo'jin want the Vilebranch destroyed?",a="Yayo'jin calls the Vilebranch a depraved lot who prey on other trolls and humanoids. She says the region's filth falls to you to destroy.",al={"why revantusk fight vilebranch","vilebranch cannibalism","revantusk vilebranch conflict"}},{q="Where can the Vilebranch trolls be found?",a="The Vilebranch gather around the Shaol'watha and Agol'watha temples, in the Hinterlands' north by northeast.",al={"shaolwatha location","agolwatha location","where are vilebranch soothsayers"}},{q="Which Vilebranch does Yayo'jin want destroyed?",a="Yayo'jin wants the Vilebranch Scalpers and Vilebranch Soothsayers destroyed.",al={"cannibalistic cousins targets","who do i kill for cannibalistic cousins"}},{q="Where is Zul'jin?",a="Zul'jin is not in the Hinterlands. Yayo'jin says he could wipe out the Vilebranch with ease, but he is away, leaving the Revantusk to their own devices.",al={"is zuljin here","where is zuljin hinterlands","zul'jin status"}}},kw={"agol'watha","cannibalistic cousins","mystic yayo'jin","revantusk village","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},rel={"zone:hinterlands","topic:troll"},m={start="Mystic Yayo'jin",["end"]="Mystic Yayo'jin",level="48",faction="Horde",id=7844},src={"Wowpedia: Cannibalistic Cousins"}}
E["quest:7845"] = {t="quest",n="Kidnapped Elder Torntusk!",z="hinterlands",s="At Revantusk Village, Primal Torntusk asks you to save her mate after a bold midnight raid. Her spies say Elder Torntusk is alive atop Jintha'alor.",h="At Revantusk Village, Primal Torntusk asks you to save her mate after a bold midnight raid.",sec={{t="A Midnight Raid",b="Vilebranch savages struck Revantusk Village at midnight and seized Elder Torntusk, Primal Torntusk's mate. Her spies say he is alive, held prisoner atop Jintha'alor, the Vilebranch capital in the southern Hinterlands. Primal Torntusk fears the village could not bear to lose him.",sp=0},{t="The Faceless Blood God",b="Vile Priestess Hexx is said to be preparing Elder Torntusk for sacrifice to Hakkar, the faceless blood God.",sp=0},{t="Once You Reach Him",b="Elder Torntusk is within reach, but the guards surely know you have arrived. Move quickly.",sp=1}},faq={{q="Who took Elder Torntusk?",a="Vilebranch savages took Elder Torntusk in a bold midnight raid on Revantusk Village.",al={"who kidnapped elder torntusk","who took torntusk","kidnappers of torntusk"}},{q="Where is Elder Torntusk being held?",a="Primal Torntusk's spies say Elder Torntusk is a prisoner atop Jintha'alor, the Vilebranch capital in the southern Hinterlands.",al={"elder torntusk location","where is elder torntusk","where is torntusk captive"}},{q="What fate awaits Elder Torntusk atop Jintha'alor?",a="Sacrifice. Word is that Vile Priestess Hexx is readying Elder Torntusk as an offering to Hakkar, the faceless blood God.",al={"why was torntusk captured","what do vilebranch want with torntusk","hexx sacrifice torntusk"}},{q="Who is Primal Torntusk?",a="Primal Torntusk is Elder Torntusk's mate, and she asks you to save him.",al={"who is primal torntusk","primal torntusk mate"}}},kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},rel={"quest:7846","quest:7847","zone:hinterlands"},m={start="Primal Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7845},src={"Wowpedia: Kidnapped Elder Torntusk!"}}
E["quest:7846"] = {t="quest",n="Recover the Key!",z="hinterlands",s="At Jintha'alor, Elder Torntusk is shackled and asks you to free him. Hitah'ya the Keeper holds his key in a guarded cave nearby.",h="At Jintha'alor, Elder Torntusk is shackled and asks you to free him.",sec={{t="The Keeper's Cave",b="After Kidnapped Elder Torntusk!, you find Elder Torntusk shackled at Jintha'alor. Hitah'ya the Keeper keeps the key to his bindings in a nearby cave, where she is well guarded. Elder Torntusk asks you to kill her and bring back the key. Then he can loosen his shackles and return home.",sp=0},{t="Elder Torntusk's Thanks",b="With the key, Elder Torntusk gets to his feet. He thanks you and says the Revantusk will hear of your deeds.",sp=1}},faq={{q="Who holds the key to Elder Torntusk's shackles?",a="Hitah'ya the Keeper holds the key to Elder Torntusk's shackles. He says she is in a nearby cave, where she is well guarded.",al={"who has the key","hitahya the keeper","where is the shackle key"}},{q="Where is Elder Torntusk held?",a="Elder Torntusk is held at Jintha'alor.",al={"where is elder torntusk","torntusk location","jintha'alor torntusk"}},{q="Why does Elder Torntusk need the key?",a="The key opens Elder Torntusk's shackles. He says he can return home once he is free.",al={"why the shackle key","what is the key for"}}},kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recover the key","revantusk","shackle key"},rel={"quest:7845","quest:7847","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7846,ri={"Shackle Key (The Hinterlands)"}},src={"Wowpedia: Recover the Key!"}}
E["quest:7847"] = {t="quest",n="Return to Primal Torntusk",z="hinterlands",s="Elder Torntusk is free and sends you to Revantusk Village with word for his mate, Primal Torntusk.",h="Elder Torntusk is free and sends you to Revantusk Village with word for his mate, Primal Torntusk.",sec={{t="News for His Mate",b="Elder Torntusk is free of his bindings and asks you to return to Revantusk Village. Tell his mate, Primal Torntusk, that he is coming home.",sp=0},{t="The Village Is Grateful",b="Primal Torntusk thanks you for serving the Revantusk. The village owes you a deep debt of gratitude.",sp=1}},faq={{q="Who sends you on this journey?",a="Elder Torntusk sends you to carry news of his rescue to his mate.",al={"who starts return to primal torntusk","elder torntusk quest giver"}},{q="Where is Primal Torntusk located?",a="Primal Torntusk is at Revantusk Village in the Hinterlands.",al={"where is primal torntusk","primal torntusk location","where to turn in return to primal torntusk"}},{q="What am I supposed to tell Primal Torntusk?",a="Tell Primal Torntusk that Elder Torntusk is coming home.",al={"what to tell primal torntusk","torntusk message"}},{q="What came before this journey?",a="This follows Recover the Key!, after the earlier effort that began in Kidnapped Elder Torntusk!.",al={"previous quest","primal torntusk quest chain"}}},kw={"elder torntusk","hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},rel={"quest:7846","quest:7845","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Primal Torntusk",level="51",faction="Horde",id=7847},src={"Wowpedia: Return to Primal Torntusk"}}
E["quest:7849"] = {t="quest",n="Separation Anxiety",z="hinterlands",s="Huntsman Markhor grieves for his twin, Malkhor, in Revantusk Village. The Vilebranch took Malkhor in the raid that took Torntusk's mate. Markhor believes Malkhor's soul can still be rescued, though his life is beyond saving. So he asks you to recover the remains.",h="Huntsman Markhor grieves for his twin, Malkhor, in Revantusk Village.",sec={{t="A Twin's Loss",b="Many in Revantusk Village have lost loved ones to the wilds, Markhor says. His own grief is for his twin brother, Malkhor. The Vilebranch took Malkhor in the raid that took Torntusk's mate. His captors killed him swiftly and brutally; he was not fated to live.",sp=0},{t="Where the Remains Lie",b="The Vilebranch fed Malkhor's remains to their oozes and wolves. Near the top of the temple of Jintha'alor are a refuse pit filled with oozes and a wolf den. His bones rest in a sludge pit near the top tier, while his skull lies on the tier itself. Markhor plans to carry the remains to Yayo'jin, who will prepare them for a proper burial.",sp=0}},faq={{q="Who was Huntsman Malkhor?",a="Malkhor was Huntsman Markhor's twin brother. The Vilebranch took him in the raid that also took Torntusk's mate, then killed him swiftly and brutally.",al={"who is malkhor","markhors brother","malkhor lore"}},{q="Where were Malkhor's remains taken?",a="The Vilebranch fed Malkhor's remains to their oozes and wolves. His skull lies on Jintha'alor's top tier, while his bones rest in a sludge pit near that tier.",al={"where are the bones","where is malkhors skull","jintha'alor remains"}},{q="Who will prepare Malkhor for burial?",a="Markhor will take Malkhor's remains to Yayo'jin, who will prepare them for a proper burial.",al={"burial for malkhor","who is yayojin","yayo'jin"}},{q="Why does Markhor need the bones returned?",a="Markhor says Malkhor's life is beyond saving, but his soul can still be rescued. He wants the remains recovered so that Malkhor's soul may be saved.",al={"why recover remains","save malkhors soul","saving his soul"}}},kw={"bones","hinterlands","jintha'alor","malkhor","markhor","revantusk","skull","vilebranch","yayo'jin"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="50",faction="Horde",id=7849,ri={"Huntsman Malkhor's Bones","Huntsman Malkhor's Skull"}},src={"Wowpedia: Separation Anxiety (quest)"}}
E["quest:7850"] = {t="quest",n="Dark Vessels",z="hinterlands",s="In Revantusk Village, Primal Torntusk says the Vilebranch fight with a fury beyond the natural. He blames Vile Priestess Hexx's foul magic and asks you to take the tainted blood vessels from Jintha'alor, so he can cleanse them.",h="In Revantusk Village, Primal Torntusk says the Vilebranch fight with a fury beyond the natural.",sec={{t="The Vilebranch Fury",b="Across Jintha'alor, tainted blood vessels bear the power of the faceless blood God. That power strengthens the Vilebranch and drives them mad. Torntusk believes taking the vessels away and cleansing them will loosen the blood God's grip on the trolls.",sp=0},{t="After the Vessels Return",b="Returning the vessels lifts the dark energy compelling the Vilebranch, though only for now. Torntusk warns you to watch for evil, for a fallen priestess is soon replaced by another.",sp=1}},faq={{q="Who gives the quest Dark Vessels?",a="Primal Torntusk asks you in Revantusk Village, in the Hinterlands.",al={"who gives dark vessels","dark vessels questgiver"}},{q="Where are the tainted vessels located?",a="The tainted blood vessels lie throughout Jintha'alor in the Hinterlands.",al={"where are dark vessels","vessels of tainted blood location","find tainted blood"}},{q="Why are the Vilebranch trolls so ferocious?",a="Primal Torntusk blames the foul magic of Vile Priestess Hexx. The tainted blood vessels also carry the faceless blood God's power, which strengthens the Vilebranch and drives them mad.",al={"why are vilebranch crazy","vilebranch madness","vilebranch ferocity"}},{q="What does Primal Torntusk plan to do with the vessels?",a="Torntusk plans to cleanse the vessels and loosen the faceless blood God's grip on the Vilebranch.",al={"why collect the vessels","what happens to the blood vessels"}}},kw={"blood god","dark vessels","jintha'alor","primal torntusk","revantusk village","tainted blood","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Primal Torntusk",["end"]="Primal Torntusk",level="50",faction="Horde",id=7850,ri={"Vessel of Tainted Blood"}},src={"Wowpedia: Dark Vessels (Classic)"}}
E["quest:7861"] = {t="quest",n="Wanted: Vile Priestess Hexx and Her Minions",z="hinterlands",s="Primal Torntusk has sent you to Jintha'alor to bring Vile Priestess Hexx and her minions to justice. He offers a grand prize for slaying Hexx and her elite Aman'zasi guard.",h="Primal Torntusk has sent you to Jintha'alor to bring Vile Priestess Hexx and her minions to justice.",sec={{t="A Strike at Jintha'alor",b="Primal Torntusk sends you after Vile Priestess Hexx and her minions. They are atop Jintha'alor in the Hinterlands, where Hexx's elite Aman'zasi guards stand with her. Slay them, then report to Torntusk at Revantusk Village.",sp=0}},faq={{q="Who posted the bounty for Vile Priestess Hexx?",a="Primal Torntusk ordered the bounty and offers a grand prize for slaying the priestess and her guard.",al={"who wants hexx dead","who gave this bounty","priestess hexx quest giver"}},{q="Where can Vile Priestess Hexx and her guards be found?",a="Vile Priestess Hexx and her guards are atop Jintha'alor in the Hinterlands.",al={"where is hexx","vile priestess hexx location","amanzasi guards location"}},{q="Who must be slain to fulfill the bounty?",a="Slay Priestess Hexx and her elite Aman'zasi guard of the Vilebranch.",al={"hexx bounty objectives","who to kill for hexx"}},{q="Where is the bounty turned in?",a="After slaying the priestess and her guard, report to Primal Torntusk at Revantusk Village.",al={"where to turn in hexx bounty","primal torntusk location"}}},kw={"aman'zasi","hexx","hinterlands","jintha'alor","primal torntusk","revantusk village","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7861},src={"Wowpedia: Wanted: Vile Priestess Hexx and Her Minions"}}
E["quest:7862"] = {t="quest",n="Job Opening: Guard Captain of Revantusk Village",z="hinterlands",s="Revantusk Village needs a new leader for its guard. Applicants must prove themselves against four kinds of Vilebranch and bring an application to Primal Torntusk.",h="Revantusk Village needs a new leader for its guard.",sec={{t="A Vacant Post",b="Guard Captain Malkhor has been lost, leaving Revantusk's guard without a captain once more. The notice calls on anyone who wants to lead the guard to complete its work and send an application to Primal Torntusk.",sp=0},{t="Proving Worth",b="To seek the captaincy, defeat Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters. Then return to Primal Torntusk in Revantusk Village.",sp=0}},faq={{q="Why is the position of Guard Captain open?",a="Guard Captain Malkhor was lost, leaving the captaincy vacant again.",al={"why is guard captain open","what happened to malkhor","who was previous captain"}},{q="Who receives the application once the enemies are slain?",a="Bring the application to Primal Torntusk in Revantusk Village.",al={"who do i turn this in to","where to submit application","who evaluates the applicants"}},{q="Which enemies must be defeated to qualify?",a="Applicants must defeat Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters.",al={"which vilebranch to kill","job opening targets","who do i kill for guard captain"}}},kw={"berserker","blood drinker","guard captain","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7862},src={"Wowpedia: Job Opening: Guard Captain of Revantusk Village"}}
E["quest:836"] = {t="quest",n="Rescue OOX-09/HL!",z="hinterlands",s="Beyond Overlook Cliff, OOX-09/HL needs your help reaching the shore. Oglethorpe Obnoticus speaks through the fallen robot and asks you to escort it there. He waits in Booty Bay afterward.",h="Beyond Overlook Cliff, OOX-09/HL needs your help reaching the shore.",sec={{t="A Walk to the Shore",b="Oglethorpe's voice crackles from the robot again. OOX-09/HL needs an open, safe place for its lengthy take-off procedure, and the shoreline beyond Overlook Cliff will do. Its built-in cloaking cannot yet be used. Oglethorpe needs time to make it work again.",sp=0},{t="Word in Booty Bay",b="When OOX-09/HL reaches the shore safely, Oglethorpe Obnoticus asks you to speak with him in Booty Bay.",sp=0}},faq={{q="Where does the robot need to be escorted?",a="Take OOX-09/HL to the shoreline beyond Overlook Cliff. There, it has room to begin its take-off.",al={"where does oox-09 go","hinterlands chicken escort destination","overlook cliff shore"}},{q="Who is responsible for creating this homing robot?",a="The gnome Oglethorpe Obnoticus created the robot. He is in Booty Bay.",al={"who made oox-09","oox creator","who built the chicken"}},{q="Why can't the robot simply take off where it was found?",a="The lengthy take-off needs an open, safe place. Oglethorpe also needs time to make the robot's cloaking work again.",al={"why does the chicken walk","why escort oox-09"}},{q="Where do you go once the escort reaches the shore?",a="Once OOX-09/HL is safely at the shore, Oglethorpe Obnoticus asks you to meet him in Booty Bay.",al={"where to turn in rescue oox-09","who do i report to","oglethorpe location"}},{q="What came before this escort?",a="This follows Find OOX-09/HL!, when you carried the distress beacon to the crashed robot.",al={"oox-09 previous quest","prerequisite for rescue oox-09"}}},kw={"booty bay","cloaking","homing robot","oglethorpe obnoticus","overlook cliff","oox-09/hl"},rel={"quest:485","zone:hinterlands","subzone:booty-bay"},m={start="Homing Robot OOX-09/HL",["end"]="Oglethorpe Obnoticus",level="48",id=836},src={"Wowpedia: Rescue OOX-09/HL!"}}
E["zone:hinterlands"] = {t="zone",n="The Hinterlands",z="hinterlands",s="The Hinterlands still bear the Amani's old claims, while Wildhammer dwarves hold Aerie Peak. Forest trolls keep their ruined temples, and the Revantusk have made a village on the eastern coast.",h="The Hinterlands still bear the Amani's old claims, while Wildhammer dwarves hold Aerie Peak.",sec={{t="A Land of Clashing Claims",b="The Amani forest trolls ruled the Hinterlands long before humans or dwarves came to northern Lordaeron. Their defeat in the ancient Troll Wars broke the empire into separate tribes. Centuries later, the War of the Three Hammers drove the Wildhammer dwarves from Grim Batol.\n\nThey migrated north and settled above ground at Aerie Peak. There, they tamed native gryphons and kept their shamanic traditions as they built a great stronghold in the heights. The forest trolls saw them as squatters on ancestral land. Skirmishes and raids have kept the feud alive ever since.",sp=0},{t="Tribes of the Forest",b="Three forest troll tribes occupy the dense woods and ruined temples. The strongest are the brutal Vilebranch, who hold the terraced temple city of Jintha'Alor and the towering Altar of Zul. Farther south, the weaker Witherbark cling to Shadra'Alor and Hiri'Watha.\n\nThe nomadic Revantusk were long scorned by their cousins and had no true home. After the Third War, they made a treaty with Thrall's New Horde. With aid from orcs and Forsaken, they founded Revantusk Village on the eastern sea cliffs and claimed a coastal stronghold of their own.",sp=0},{t="The Slumbering Rift",b="Seradane, the great tree in the northern Hinterlands, shelters a portal to the Emerald Dream. Green dragons and creatures of nature guard the grove. Now the Emerald Nightmare seeps across the portal's threshold, twisting once-benevolent drakes and dragonspawn into furious guardians.",sp=1}},faq={{q="How do I get to the Hinterlands?",a="Travelers from either faction enter the Hinterlands from Hillsbrad Foothills. They go northeast through a mountain pass beyond Durnholde Keep. Alliance travelers follow the road to Aerie Peak, while Horde travelers cross east through the wilderness to Revantusk Village on the coast.",al={"hinterlands entrance","how to enter hinterlands","getting to hinterlands"}},{q="Who rules Aerie Peak?",a="Falstad Wildhammer, Lord of Aerie Peak, leads the Wildhammer clan there. Thane Kurdran Wildhammer led the clan during the Second War.",al={"wildhammer leader","who leads wildhammer","aerie peak ruler"}},{q="Why are the Revantusk trolls allied with the Horde?",a="The nomadic Revantusk sought protection and an end to wandering. The hostile Vilebranch and Witherbark rejected Horde emissaries. The New Horde gave the Revantusk resources and soldiers to build Revantusk Village on the coast, earning their loyalty against local rivals.",al={"revantusk horde","why troll horde hinterlands","revantusk village lore"}},{q="What is Jintha'Alor?",a="Jintha'Alor is an ancient fortress cut into the southern cliffs in many tiers. It is the chief stronghold of the ruthless Vilebranch, with sacrificial altars and elite warriors. Its witch doctors perform blood rites for their dark loas.",al={"jintha'alor lore","troll city hinterlands","vilebranch city"}},{q="What is the Great Tree at Seradane?",a="Seradane, one of Azeroth's Great Trees, shelters a portal to the Emerald Dream. Green dragons and wildkin watch over the grove.",al={"seradane portal","big tree hinterlands","green dragon hinterlands"}},{q="What is Quel'Danil Lodge?",a="Quel'Danil Lodge is a forest retreat kept by Highvale high elves. The Scourge spared it from a direct assault on Quel'Thalas. Its rangers and scholars work with nearby Wildhammer dwarves, sharing intelligence about hostile forest trolls.",al={"high elf lodge hinterlands","queldanil","elves in hinterlands"}}},ang={["race:Dwarf"]="As a Wildhammer or visiting Bronzebeard, you find dwarven life at Aerie Peak beneath open skies. Shamanic power and legendary gryphons shape life there.",["race:Troll"]="In the Hinterlands, ancient Amani glory lives on as bloodlines clash over temple steps. The Revantusk show that forest trolls still have a place in the New Horde.",["faction:Alliance"]="The Wildhammer dwarves prize their fierce independence. Aid their outposts and the high elves of Quel'Danil to build goodwill against shared troll threats.",["faction:Horde"]="Revantusk Village gives the Horde an eastern beachhead in northern Lordaeron. To hold it, you must beat back the fierce Vilebranch.",["class:Druid"]="Seradane's ancient tree is closely tied to the Emerald Dream. Watch carefully for the creeping rot of the Nightmare."},kw={"aerie peak","gryphon","hinterlands","jintha'alor","quel'danil","revantusk","seradane","vilebranch","wildhammer","witherbark"},rel={"topic:wildhammer-clan","topic:new-horde","topic:emerald-dream","topic:troll","subzone:durnholde-keep","zone:arathi","zone:hillsbrad","zone:westernplaguelands"},src={"Hinterlands"}}
